async fn trace_corpus_db_mirror_from_env() -> anyhow::Result<Option<Arc<dyn Database>>> {
    if !env_truthy("TRACE_COMMONS_DB_DUAL_WRITE") {
        return Ok(None);
    }

    let url = std::env::var("DATABASE_URL")
        .context("TRACE_COMMONS_DB_DUAL_WRITE requires DATABASE_URL")?;
    let pool_size = std::env::var("DATABASE_POOL_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(5);
    let config = DatabaseConfig::from_postgres_url(&url, pool_size);
    let db = trace_commons_server::db::connect_from_config(&config)
        .await
        .context("failed to connect Trace Commons DB dual-write mirror")?;
    tracing::info!("Trace Commons PostgreSQL DB dual-write mirror enabled");
    Ok(Some(db))
}

async fn validate_required_postgres_trace_rls_ready(
    db_mirror: Option<&Arc<dyn Database>>,
) -> anyhow::Result<()> {
    let Some(db) = db_mirror else {
        anyhow::bail!(
            "{TRACE_COMMONS_REQUIRE_POSTGRES_TRACE_RLS_READY} requires TRACE_COMMONS_DB_DUAL_WRITE with DATABASE_URL"
        );
    };
    let diagnostics = db
        .trace_corpus_rls_diagnostics()
        .await
        .context("failed to inspect Trace Commons PostgreSQL RLS diagnostics")?
        .ok_or_else(|| {
            anyhow::anyhow!(
                "{TRACE_COMMONS_REQUIRE_POSTGRES_TRACE_RLS_READY} requires a PostgreSQL trace DB mirror"
            )
        })?;
    validate_required_postgres_trace_rls_diagnostics(&diagnostics)
}

fn validate_required_postgres_trace_rls_diagnostics(
    diagnostics: &TraceCorpusRlsDiagnostics,
) -> anyhow::Result<()> {
    if diagnostics.production_ready() {
        return Ok(());
    }
    anyhow::bail!(
        "{TRACE_COMMONS_REQUIRE_POSTGRES_TRACE_RLS_READY} requires complete Trace Commons RLS policy coverage, enabled RLS, FORCE ROW LEVEL SECURITY on every Trace Commons table, and a non-bypassing runtime role; expected_tables={}, policies={}, rls_enabled={}, force_rls_enabled={}, missing_policies={}, rls_disabled={}, force_rls_disabled={}, expression_mismatches={}, bypass_role={}",
        diagnostics.expected_table_count,
        diagnostics.policy_installed_count,
        diagnostics.rls_enabled_count,
        diagnostics.force_rls_enabled_count,
        diagnostics.missing_policy_tables.len(),
        diagnostics.rls_disabled_tables.len(),
        diagnostics.force_rls_disabled_tables.len(),
        diagnostics.policy_expression_mismatch_tables.len(),
        diagnostics.current_role_bypasses_rls,
    )
}

fn env_truthy(key: &str) -> bool {
    std::env::var(key).ok().is_some_and(|value| {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

fn parse_trace_rollout_tenant_ids_from_env(key: &str) -> anyhow::Result<BTreeSet<String>> {
    match std::env::var(key) {
        Ok(configured) => parse_trace_rollout_tenant_ids(key, &configured),
        Err(std::env::VarError::NotPresent) => Ok(BTreeSet::new()),
        Err(error) => Err(error).with_context(|| format!("failed to read {key}")),
    }
}

fn parse_trace_rollout_tenant_ids(key: &str, configured: &str) -> anyhow::Result<BTreeSet<String>> {
    let mut tenant_ids = BTreeSet::new();
    for tenant_id in configured.split(',').map(str::trim) {
        if tenant_id.is_empty() {
            continue;
        }
        anyhow::ensure!(
            !tenant_id.contains(':') && !tenant_id.contains(';') && !tenant_id.contains('/'),
            "{key} contains an invalid tenant id"
        );
        tenant_ids.insert(tenant_id.to_string());
    }
    Ok(tenant_ids)
}

