fn trimmed_optional_string(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn trace_tenant_policy_projection_hash(
    policy_version: &str,
    allowed_consent_scopes: &[String],
    allowed_uses: &[String],
) -> anyhow::Result<String> {
    #[derive(Serialize)]
    struct TenantPolicyAuditProjection<'a> {
        policy_version: &'a str,
        allowed_consent_scopes: &'a [String],
        allowed_uses: &'a [String],
    }

    let projection = TenantPolicyAuditProjection {
        policy_version,
        allowed_consent_scopes,
        allowed_uses,
    };
    let json = serde_json::to_string(&projection)
        .context("failed to serialize trace tenant policy audit projection")?;
    Ok(sha256_prefixed(&json))
}

fn trace_tenant_access_grant_projection_hash(
    action: &str,
    grant: &TraceTenantAccessGrantResponse,
) -> anyhow::Result<String> {
    #[derive(Serialize)]
    struct TenantAccessGrantAuditProjection<'a> {
        action: &'a str,
        grant_id: Uuid,
        principal_ref: &'a str,
        role: StorageTraceTenantAccessGrantRole,
        status: StorageTraceTenantAccessGrantStatus,
        allowed_consent_scope_count: usize,
        allowed_use_count: usize,
        issuer_configured: bool,
        audience_configured: bool,
        subject_configured: bool,
        expires_at: Option<DateTime<Utc>>,
        revoked_at: Option<DateTime<Utc>>,
    }
    let projection = TenantAccessGrantAuditProjection {
        action,
        grant_id: grant.grant_id,
        principal_ref: &grant.principal_ref,
        role: grant.role,
        status: grant.status,
        allowed_consent_scope_count: grant.allowed_consent_scopes.len(),
        allowed_use_count: grant.allowed_uses.len(),
        issuer_configured: grant.issuer.is_some(),
        audience_configured: grant.audience.is_some(),
        subject_configured: grant.subject.is_some(),
        expires_at: grant.expires_at,
        revoked_at: grant.revoked_at,
    };
    let json = serde_json::to_string(&projection)
        .context("failed to serialize trace tenant access grant audit projection")?;
    Ok(sha256_prefixed(&json))
}

async fn append_tenant_access_grant_update_audit(
    state: &AppState,
    tenant: &TenantAuth,
    grant: &TraceTenantAccessGrantResponse,
    action: &'static str,
) -> anyhow::Result<()> {
    let projection_hash = trace_tenant_access_grant_projection_hash(action, grant)?;
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent::tenant_access_grant_update(tenant, action, grant, &projection_hash),
        StorageTraceAuditAction::PolicyUpdate,
        StorageTraceAuditSafeMetadata::TenantAccessGrant {
            action: action.to_string(),
            role: grant.role,
            status: grant.status,
            allowed_consent_scope_count: grant.allowed_consent_scopes.len() as u32,
            allowed_use_count: grant.allowed_uses.len() as u32,
            grant_projection_hash: projection_hash,
        },
    )
    .await
}

async fn submit_trace_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(mut envelope): Json<TraceContributionEnvelope>,
) -> ApiResult<Json<TraceSubmissionReceipt>> {
    let tenant = authorize_tenant_access_grant_ctx(
        state.as_ref(),
        authenticate_ctx(state.as_ref(), &headers)?,
    )
    .await?;
    validate_envelope(&envelope)?;

    if let Some(existing) = tenant
        .read_submission_record(&state.root, envelope.submission_id)
        .map_err(internal_error)?
    {
        if !tenant.can_access_submission(&existing) {
            return Err(api_error(
                StatusCode::CONFLICT,
                "submission id already belongs to another principal",
            ));
        }
        let receipt = receipt_from_record(&existing);
        append_audit_event(
            &state.root,
            tenant.tenant_id(),
            tenant.idempotent_submit_audit_event(envelope.submission_id),
        )
        .map_err(internal_error)?;
        return Ok(Json(receipt));
    }

    let tenant_policy = tenant_submission_policy_for_request(state.as_ref(), tenant.auth()).await?;
    enforce_signed_claim_submission_restrictions(&tenant, &envelope)?;
    enforce_tenant_submission_policy(
        tenant.auth(),
        &envelope,
        tenant_policy.as_ref(),
        state.require_tenant_submission_policy,
    )?;

    rescrub_trace_envelope(&mut envelope);
    let existing_revocations = read_revocations_for_submit(state.as_ref(), tenant.tenant_id())
        .await
        .map_err(internal_error)?;
    let existing_derived =
        read_all_derived_records(&state.root, tenant.tenant_id()).map_err(internal_error)?;
    let derived_precheck = build_derived_precheck(&envelope, &existing_derived);
    ensure_not_revoked_by_tombstone(
        &existing_revocations,
        envelope.submission_id,
        &envelope.privacy.redaction_hash,
        &derived_precheck.canonical_summary_hash,
    )?;
    enforce_submission_quota(state.as_ref(), &tenant)?;
    apply_embedding_precheck(&mut envelope, &derived_precheck);
    apply_credit_estimate_to_envelope(&mut envelope);
    let corpus_status = status_for_risk(envelope.privacy.residual_pii_risk);
    if corpus_status != TraceCorpusStatus::Accepted {
        envelope.value.credit_points_pending = 0.0;
        envelope.value.explanation = vec![
            "Submission is quarantined until privacy review completes; credit is held at 0.0."
                .to_string(),
        ];
        envelope.value_card.user_visible_explanation = envelope.value.explanation.clone();
    }

    let stored_envelope = store_envelope(
        &state,
        tenant.tenant_id(),
        corpus_status,
        "submitted-envelope",
        &envelope,
    )
    .map_err(internal_error)?;
    let derived_record = build_derived_record(
        tenant.tenant_id(),
        corpus_status,
        &envelope,
        derived_precheck,
    );
    let retention_policy = retention_policy_for_trace(&envelope);
    let received_at = Utc::now();
    let expires_at = retention_policy
        .max_age_days
        .map(|days| received_at + Duration::days(i64::from(days)));
    let record = TraceCommonsSubmissionRecord {
        tenant_id: tenant.tenant_id().to_string(),
        tenant_storage_ref: tenant.tenant_storage_ref(),
        auth_principal_ref: tenant.principal_ref().to_string(),
        submitted_tenant_scope_ref: tenant.submitted_tenant_scope_ref(),
        contributor_pseudonym: envelope.contributor.pseudonymous_contributor_id.clone(),
        submission_id: envelope.submission_id,
        trace_id: envelope.trace_id,
        status: corpus_status,
        privacy_risk: envelope.privacy.residual_pii_risk,
        submission_score: envelope.value.submission_score,
        credit_points_pending: envelope.value.credit_points_pending,
        credit_points_final: envelope.value.credit_points_final,
        consent_scopes: envelope.consent.scopes.clone(),
        allowed_uses: envelope.trace_card.allowed_uses.clone(),
        redaction_counts: envelope.privacy.redaction_counts.clone(),
        received_at,
        review_assigned_to_principal_ref: None,
        review_assigned_at: None,
        review_lease_expires_at: None,
        review_due_at: None,
        retention_policy_id: retention_policy.name,
        expires_at,
        purged_at: None,
        object_key: stored_envelope.object_key,
        artifact_receipt: stored_envelope.artifact_receipt,
    };
    if state.require_db_mirror_writes {
        let mirror_result =
            mirror_submission_to_db(&state, tenant.auth(), &record, &derived_record, &envelope)
                .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(%error, submission_id = %record.submission_id, "Trace Commons DB dual-write mirror failed");
            cleanup_submission_file_side_writes(state.as_ref(), &record).map_err(internal_error)?;
        }
        enforce_db_mirror_write_result(state.as_ref(), "submission", mirror_result)
            .map_err(internal_error)?;
        write_submission_record(&state.root, &record).map_err(internal_error)?;
        write_derived_record(&state.root, &derived_record).map_err(internal_error)?;
        append_audit_event(
            &state.root,
            tenant.tenant_id(),
            tenant.submitted_audit_event(&record),
        )
        .map_err(internal_error)?;
    } else {
        write_submission_record(&state.root, &record).map_err(internal_error)?;
        write_derived_record(&state.root, &derived_record).map_err(internal_error)?;
        append_audit_event(
            &state.root,
            tenant.tenant_id(),
            tenant.submitted_audit_event(&record),
        )
        .map_err(internal_error)?;
        let mirror_result =
            mirror_submission_to_db(&state, tenant.auth(), &record, &derived_record, &envelope)
                .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(%error, submission_id = %record.submission_id, "Trace Commons DB dual-write mirror failed");
        }
        enforce_db_mirror_write_result(state.as_ref(), "submission", mirror_result)
            .map_err(internal_error)?;
    }

    Ok(Json(receipt_from_record(&record)))
}

