async fn revoke_submission(
    state: &AppState,
    headers: &HeaderMap,
    submission_id: Uuid,
    reason: Option<&str>,
) -> ApiResult<StatusCode> {
    let tenant = authenticate_ctx(state, headers)?;
    let mut record = tenant
        .read_submission_record(&state.root, submission_id)
        .map_err(internal_error)?;
    if let Some(record) = record.as_ref()
        && !tenant.can_access_submission(record)
    {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "trace submission not found",
        ));
    }
    let db_record = if record.is_none() {
        db_submission_record_for_revocation(state, tenant.tenant_id(), submission_id)
            .await
            .map_err(internal_error)?
    } else {
        None
    };
    if let Some(db_record) = db_record.as_ref()
        && !tenant.can_access_storage_submission(db_record)
    {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "trace submission not found",
        ));
    }
    if record.is_none() && db_record.is_none() {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "trace submission not found",
        ));
    }
    let db_record_for_privileged_abac = db_record
        .clone()
        .and_then(trace_commons_record_from_storage_submission)
        .transpose()
        .map_err(internal_error)?;
    let owner_self_revocation = record
        .as_ref()
        .is_some_and(|record| principal_can_self_revoke_submission(tenant.auth(), record))
        || db_record.as_ref().is_some_and(|record| {
            principal_can_self_revoke_storage_submission(tenant.auth(), record)
        });
    if tenant.role().can_review() && !owner_self_revocation {
        let source_record = record
            .as_ref()
            .or(db_record_for_privileged_abac.as_ref())
            .ok_or_else(|| {
                internal_error("trace submission could not be projected for privileged revocation")
            })?;
        let privileged_policy =
            tenant_privileged_action_policy_for_request(state, tenant.auth(), "revocation").await?;
        ensure_record_matches_privileged_action_policy_abac(
            source_record,
            tenant.auth(),
            privileged_policy.as_ref(),
            "revocation",
        )?;
    }
    let revocation_reason =
        trace_revocation_reason_for_request(tenant.auth(), owner_self_revocation, reason)?;
    let mut derived = tenant
        .read_derived_record(&state.root, submission_id)
        .map_err(internal_error)?;
    let tombstone = TraceCommonsRevocation {
        tenant_id: tenant.tenant_id().to_string(),
        tenant_storage_ref: tenant.tenant_storage_ref(),
        submission_id,
        revoked_at: Utc::now(),
        reason: revocation_reason.clone(),
        redaction_hash: record
            .as_ref()
            .and_then(|record| redaction_hash_for_record(state, record)),
        canonical_summary_hash: derived
            .as_ref()
            .map(|record| record.canonical_summary_hash.clone()),
    };
    write_revocation(&state.root, &tombstone).map_err(internal_error)?;

    let mut mirrored_record = None;
    if let Some(mut record) = record.take() {
        record.status = TraceCorpusStatus::Revoked;
        record.credit_points_final = Some(0.0);
        write_submission_record(&state.root, &record).map_err(internal_error)?;
        mirrored_record = Some(record);
    }
    if let Some(mut derived) = derived.take() {
        derived.status = TraceCorpusStatus::Revoked;
        write_derived_record(&state.root, &derived).map_err(internal_error)?;
    }
    invalidate_export_provenance_for_source(
        &state.root,
        tenant.tenant_id(),
        submission_id,
        &revocation_reason,
    )
    .map_err(internal_error)?;
    let mut benchmark_revocation_reasons = BTreeMap::new();
    benchmark_revocation_reasons.insert(submission_id, revocation_reason.clone());
    propagate_benchmark_artifact_source_invalidation(
        state,
        tenant.auth(),
        &benchmark_revocation_reasons,
        &BTreeSet::new(),
        false,
    )
    .await
    .map_err(internal_error)?;

    append_audit_event_with_db_mirror(
        state,
        tenant.auth(),
        tenant.revoked_audit_event(submission_id, &revocation_reason),
        StorageTraceAuditAction::Revoke,
        StorageTraceAuditSafeMetadata::Empty,
    )
    .await
    .map_err(internal_error)?;
    let mirror_result = mirror_revocation_to_db(
        state,
        tenant.auth(),
        submission_id,
        mirrored_record.as_ref(),
        db_record.as_ref(),
        &revocation_reason,
        None,
    )
    .await;
    if let Err(error) = &mirror_result {
        tracing::warn!(%error, %submission_id, "Trace Commons DB dual-write revocation mirror failed");
    }
    enforce_db_mirror_write_result(state, "revocation", mirror_result).map_err(internal_error)?;
    Ok(StatusCode::NO_CONTENT)
}

async fn credit_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<TraceCommonsTenantCreditResponse>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    let credit_view = read_contributor_credit_view(state.as_ref(), tenant.auth())
        .await
        .map_err(internal_error)?;
    let item_count = credit_view.records.len();
    append_audit_event_with_db_mirror(
        state.as_ref(),
        tenant.auth(),
        tenant.read_audit_event("contributor_credit", item_count),
        StorageTraceAuditAction::Read,
        StorageTraceAuditSafeMetadata::Empty,
    )
    .await
    .map_err(internal_error)?;
    let settlement_batches = read_all_credit_settlement_batches(&state.root, tenant.tenant_id())
        .map_err(internal_error)?;
    let credit_holds =
        read_all_credit_holds(&state.root, tenant.tenant_id()).map_err(internal_error)?;
    Ok(Json(
        TraceCommonsTenantCreditResponse::from_records_events_and_settlements(
            tenant.tenant_id().to_string(),
            tenant.auth(),
            credit_view.records,
            &credit_view.credit_events,
            &settlement_batches,
            &credit_holds,
        ),
    ))
}

