fn trace_review_lease_action_name(action: StorageTraceReviewLeaseAuditAction) -> &'static str {
    match action {
        StorageTraceReviewLeaseAuditAction::Claim => "claim",
        StorageTraceReviewLeaseAuditAction::Release => "release",
    }
}

fn trace_audit_reason_value<'a>(reason: Option<&'a str>, key: &str) -> Option<&'a str> {
    let prefix = format!("{key}=");
    reason?
        .split(';')
        .find_map(|part| part.strip_prefix(&prefix))
}

fn trace_audit_reason_u32(reason: Option<&str>, key: &str) -> Option<u32> {
    trace_audit_reason_value(reason, key)?.parse::<u32>().ok()
}

fn trace_audit_reason_enum<T>(reason: Option<&str>, key: &str) -> Option<T>
where
    T: DeserializeOwned,
{
    serde_json::from_value(serde_json::Value::String(
        trace_audit_reason_value(reason, key)?.to_string(),
    ))
    .ok()
}

fn trace_content_read_purpose_hash(purpose: Option<&str>) -> Option<String> {
    purpose
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .map(sha256_prefixed)
}

fn trace_content_read_audit_reason(surface: &str, purpose_hash: Option<&str>) -> String {
    let mut reason = format!("surface={surface}");
    if let Some(purpose_hash) = purpose_hash
        .map(str::trim)
        .filter(|purpose_hash| !purpose_hash.is_empty())
    {
        reason.push_str(";purpose_hash=");
        reason.push_str(purpose_hash);
    }
    reason
}

fn trace_content_read_audit_metadata(
    surface: &str,
    purpose: Option<&str>,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::TraceContentRead {
        surface: surface.to_string(),
        purpose_hash: trace_content_read_purpose_hash(purpose),
    }
}

fn trace_content_read_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    let surface = trace_audit_reason_value(reason, "surface")?.to_string();
    let purpose_hash = trace_audit_reason_value(reason, "purpose_hash")
        .map(ToOwned::to_owned)
        .or_else(|| {
            trace_audit_reason_value(reason, "purpose")
                .map(str::trim)
                .filter(|purpose| !purpose.is_empty())
                .map(sha256_prefixed)
        });
    Some(StorageTraceAuditSafeMetadata::TraceContentRead {
        surface,
        purpose_hash,
    })
}

fn tenant_policy_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    Some(StorageTraceAuditSafeMetadata::TenantPolicy {
        policy_version: trace_audit_reason_value(reason, "policy_version")?.to_string(),
        allowed_consent_scope_count: trace_audit_reason_u32(reason, "allowed_consent_scope_count")?,
        allowed_use_count: trace_audit_reason_u32(reason, "allowed_use_count")?,
        policy_projection_hash: trace_audit_reason_value(reason, "policy_projection_hash")?
            .to_string(),
    })
}

fn tenant_access_grant_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    Some(StorageTraceAuditSafeMetadata::TenantAccessGrant {
        action: trace_audit_reason_value(reason, "action")?.to_string(),
        role: trace_audit_reason_enum::<StorageTraceTenantAccessGrantRole>(reason, "role")?,
        status: trace_audit_reason_enum::<StorageTraceTenantAccessGrantStatus>(reason, "status")?,
        allowed_consent_scope_count: trace_audit_reason_u32(reason, "allowed_consent_scope_count")?,
        allowed_use_count: trace_audit_reason_u32(reason, "allowed_use_count")?,
        grant_projection_hash: trace_audit_reason_value(reason, "grant_projection_hash")?
            .to_string(),
    })
}

fn trace_review_lease_audit_action_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceReviewLeaseAuditAction> {
    trace_audit_reason_value(reason, "action").and_then(|action| match action {
        "claim" => Some(StorageTraceReviewLeaseAuditAction::Claim),
        "release" => Some(StorageTraceReviewLeaseAuditAction::Release),
        _ => None,
    })
}

fn trace_review_lease_timestamp_from_reason(
    reason: Option<&str>,
    key: &str,
) -> Option<DateTime<Utc>> {
    trace_audit_reason_value(reason, key)
        .and_then(|timestamp| DateTime::parse_from_rfc3339(timestamp).ok())
        .map(|timestamp| timestamp.with_timezone(&Utc))
}

fn ranking_worker_run_recovery_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    let ranking_worker_run_id = trace_audit_reason_value(reason, "ranking_worker_run_id")
        .and_then(|value| Uuid::parse_str(value).ok())?;
    let run_kind = trace_audit_reason_enum::<StorageTraceRankingWorkerRunKind>(reason, "run_kind")?;
    let recovered_status =
        trace_audit_reason_enum::<StorageTraceRankingWorkerRunStatus>(reason, "status")?;
    let reason_hash = trace_audit_reason_value(reason, "reason_hash")?.to_string();
    Some(StorageTraceAuditSafeMetadata::RankingWorkerRunRecovery {
        ranking_worker_run_id,
        run_kind,
        recovered_status,
        reason_hash,
    })
}

fn ranking_calibration_dataset_quarantine_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    Some(
        StorageTraceAuditSafeMetadata::RankingCalibrationDatasetQuarantine {
            calibration_dataset_hash: trace_audit_reason_value(reason, "calibration_dataset_hash")?
                .to_string(),
            target_use: trace_audit_reason_value(reason, "target_use")?.to_string(),
            policy_version: trace_audit_reason_value(reason, "policy_version")?.to_string(),
            archived_source_manifest_hash: trace_audit_reason_value(
                reason,
                "archived_source_manifest_hash",
            )?
            .to_string(),
            conflict_key_hash: trace_audit_reason_value(reason, "conflict_key_hash")?.to_string(),
            reason_hash: trace_audit_reason_value(reason, "reason_hash")?.to_string(),
        },
    )
}

fn trace_review_lease_reason(
    action: StorageTraceReviewLeaseAuditAction,
    lease_expires_at: Option<DateTime<Utc>>,
    review_due_at: Option<DateTime<Utc>>,
) -> String {
    let mut reason = format!("action={}", trace_review_lease_action_name(action));
    if let Some(lease_expires_at) = lease_expires_at {
        reason.push_str(";lease_expires_at=");
        reason.push_str(&lease_expires_at.to_rfc3339());
    }
    if let Some(review_due_at) = review_due_at {
        reason.push_str(";review_due_at=");
        reason.push_str(&review_due_at.to_rfc3339());
    }
    reason
}

