async fn credit_cycle_scheduler_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceCreditCycleSchedulerRunRequest>,
) -> ApiResult<Json<TraceCreditCycleSchedulerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_credit_cycle_scheduler_reason(&body.reason)?;
    let limit = validate_credit_cycle_scheduler_limit(body.limit)?;
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    let near_contract_id = body
        .near_contract_id
        .as_deref()
        .map(str::trim)
        .filter(|contract_id| !contract_id.is_empty())
        .map(ToOwned::to_owned);

    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let mut candidates = latest_ranking_model_versions(&model_versions)
        .into_iter()
        .filter(|model| {
            matches!(
                model.status,
                StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
            )
        })
        .filter(|model| {
            model_version
                .as_ref()
                .is_none_or(|model_version| &model.model_version == model_version)
                && policy_version
                    .as_ref()
                    .is_none_or(|policy_version| &model.policy_version == policy_version)
        })
        .cloned()
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        (
            credit_cycle_scheduler_model_status_priority(left.status),
            left.created_at,
            &left.model_version,
        )
            .cmp(&(
                credit_cycle_scheduler_model_status_priority(right.status),
                right.created_at,
                &right.model_version,
            ))
    });
    let candidate_count = candidates.len();

    let mut response = TraceCreditCycleSchedulerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        preflight_only: body.preflight_only,
        submit_near_outbox: body.submit_near_outbox,
        confirm_near_outbox: body.confirm_near_outbox,
        target_use: body.target_use,
        model_version: model_version.clone(),
        policy_version: policy_version.clone(),
        reason_hash: sha256_prefixed(&reason),
        limit,
        checked_count: 0,
        eligible_count: 0,
        started_count: 0,
        skipped_active_count: 0,
        skipped_count: 0,
        pending_after_count: 0,
        skipped_reason_counts: BTreeMap::new(),
        decisions: Vec::new(),
        cycles: Vec::new(),
    };

    for candidate in candidates.into_iter().take(limit) {
        response.checked_count += 1;
        if has_overlapping_live_ranking_worker_run(
            state.as_ref(),
            &tenant,
            TraceRankingWorkerRunKind::CreditCycle,
            body.dry_run && !body.preflight_only,
            Some(&candidate.model_version),
            Some(body.target_use),
            Some(&candidate.policy_version),
        )
        .await?
        {
            let skip_reason = "active_credit_cycle_claim";
            credit_cycle_scheduler_record_skip(&mut response, skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason.to_string()),
            );
            response.skipped_active_count += 1;
            continue;
        }
        if let Some(skip_reason) = credit_cycle_scheduler_candidate_skip_reason(
            state.as_ref(),
            &tenant,
            &candidate,
            body.target_use,
            CreditCycleSchedulerPreflightOptions {
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
                allow_at_risk_models: body.allow_at_risk_models,
            },
            CreditCycleSchedulerPreflightEvidence {
                predictions: &predictions,
                labels: &labels,
                preference_labels: &preference_labels,
            },
        ) {
            credit_cycle_scheduler_record_skip(&mut response, &skip_reason);
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Skipped,
                Some(skip_reason),
            );
            continue;
        }
        if body.preflight_only {
            response.eligible_count += 1;
            credit_cycle_scheduler_record_decision(
                &mut response,
                &candidate,
                body.target_use,
                TraceCreditCycleSchedulerDecisionAction::Eligible,
                None,
            );
            continue;
        }

        match credit_cycle_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceCreditCycleWorkerRunRequest {
                dry_run: body.dry_run,
                submit_near_outbox: body.submit_near_outbox,
                confirm_near_outbox: body.confirm_near_outbox,
                target_use: body.target_use,
                model_version: candidate.model_version.clone(),
                policy_version: candidate.policy_version.clone(),
                reason: reason.clone(),
                near_contract_id: near_contract_id.clone(),
                calibration_limit: body.calibration_limit,
                model_promotion_limit: body.model_promotion_limit,
                prediction_credit_limit: body.prediction_credit_limit,
                credit_settlement_limit: body.credit_settlement_limit,
                near_outbox_limit: body.near_outbox_limit,
                near_outbox_confirm_limit: body.near_outbox_confirm_limit,
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
                allow_at_risk_models: body.allow_at_risk_models,
            }),
        )
        .await
        {
            Ok(Json(cycle)) => {
                response.started_count += 1;
                credit_cycle_scheduler_record_decision(
                    &mut response,
                    &candidate,
                    body.target_use,
                    TraceCreditCycleSchedulerDecisionAction::Started,
                    None,
                );
                response.cycles.push(cycle);
            }
            Err((StatusCode::CONFLICT, Json(error)))
                if error.error
                    == ranking_worker_run_active_conflict_message(
                        TraceRankingWorkerRunKind::CreditCycle,
                    ) =>
            {
                let skip_reason = "active_credit_cycle_claim";
                credit_cycle_scheduler_record_skip(&mut response, skip_reason);
                credit_cycle_scheduler_record_decision(
                    &mut response,
                    &candidate,
                    body.target_use,
                    TraceCreditCycleSchedulerDecisionAction::Skipped,
                    Some(skip_reason.to_string()),
                );
                response.skipped_active_count += 1;
            }
            Err(error) => return Err(error),
        }
    }
    response.pending_after_count = candidate_count.saturating_sub(response.checked_count);
    Ok(Json(response))
}

fn validate_credit_cycle_scheduler_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit cycle scheduler requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit cycle scheduler reason is too long",
        ));
    }
    Ok(reason)
}

fn validate_credit_cycle_scheduler_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_CREDIT_CYCLE_SCHEDULER_DEFAULT_LIMIT);
    if !(1..=TRACE_CREDIT_CYCLE_SCHEDULER_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit cycle scheduler limit must be between 1 and 25",
        ));
    }
    Ok(limit)
}

fn credit_cycle_scheduler_model_status_priority(status: StorageTraceRankingModelStatus) -> u8 {
    match status {
        StorageTraceRankingModelStatus::Candidate => 0,
        StorageTraceRankingModelStatus::Active => 1,
        StorageTraceRankingModelStatus::Deprecated => 2,
        StorageTraceRankingModelStatus::Archived => 3,
    }
}

#[derive(Debug, Clone, Copy)]
struct CreditCycleSchedulerPreflightOptions {
    min_label_count: Option<usize>,
    confidence_threshold: Option<f32>,
    max_average_absolute_error_micros: Option<i64>,
    allow_at_risk_models: bool,
}

#[derive(Debug, Clone, Copy)]
struct CreditCycleSchedulerPreflightEvidence<'a> {
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
}

fn credit_cycle_scheduler_candidate_skip_reason(
    state: &AppState,
    tenant: &TenantAuth,
    candidate: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    options: CreditCycleSchedulerPreflightOptions,
    evidence: CreditCycleSchedulerPreflightEvidence<'_>,
) -> Option<String> {
    let matching_prediction_count = evidence
        .predictions
        .iter()
        .filter(|prediction| {
            ranking_prediction_matches_model_target(prediction, candidate, target_use)
        })
        .count();
    if matching_prediction_count == 0 {
        return Some("missing_prediction_evidence".to_string());
    }
    let matching_label_count = evidence
        .labels
        .iter()
        .filter(|label| label.target_use == target_use)
        .count();
    if matching_label_count == 0 {
        return Some("missing_label_evidence".to_string());
    }
    let current = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version: candidate.model_version.clone(),
            target_use,
            policy_version: candidate.policy_version.clone(),
            feature_schema_version: candidate.feature_schema_version.clone(),
            evaluation_dataset_hash: candidate.calibration_dataset_hash.clone(),
            min_label_count: options
                .min_label_count
                .unwrap_or(state.ranking_min_label_count),
            min_label_source_count: state.ranking_min_label_source_count,
            confidence_threshold: options
                .confidence_threshold
                .unwrap_or(state.ranking_min_confidence_threshold),
            max_average_absolute_error_micros: options
                .max_average_absolute_error_micros
                .unwrap_or(state.ranking_max_average_absolute_error_micros),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    );
    if current.joined_label_prediction_count == 0 {
        return Some("missing_joined_label_evidence".to_string());
    }
    if !current.promotable {
        return Some(
            current
                .reason_codes
                .first()
                .cloned()
                .unwrap_or_else(|| "calibration_not_promotable".to_string()),
        );
    }
    if !options.allow_at_risk_models {
        let pairwise = ranking_pairwise_evaluation_model_report(
            candidate,
            target_use,
            evidence.predictions,
            evidence.preference_labels,
        );
        if pairwise.joined_pair_prediction_count < state.ranking_min_pairwise_label_count {
            return Some("pairwise_evidence_below_threshold".to_string());
        }
        if pairwise.joined_pair_prediction_count > 0
            && pairwise
                .pairwise_accuracy_micros
                .is_some_and(|accuracy| accuracy < state.ranking_min_pairwise_accuracy_micros)
        {
            return Some("pairwise_accuracy_below_threshold".to_string());
        }
    }
    None
}

fn credit_cycle_scheduler_record_decision(
    response: &mut TraceCreditCycleSchedulerRunResponse,
    candidate: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    action: TraceCreditCycleSchedulerDecisionAction,
    skip_reason: Option<String>,
) {
    response
        .decisions
        .push(TraceCreditCycleSchedulerCandidateDecision {
            model_version: candidate.model_version.clone(),
            model_status: candidate.status,
            target_use,
            policy_version: candidate.policy_version.clone(),
            action,
            skip_reason,
        });
}

fn credit_cycle_scheduler_record_skip(
    response: &mut TraceCreditCycleSchedulerRunResponse,
    reason: &str,
) {
    response.skipped_count += 1;
    *response
        .skipped_reason_counts
        .entry(reason.to_string())
        .or_insert(0) += 1;
}

async fn credit_cycle_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceCreditCycleWorkerRunRequest>,
) -> ApiResult<Json<TraceCreditCycleWorkerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit cycle worker run requires a non-empty reason",
        ));
    }
    let near_contract_id = body
        .near_contract_id
        .as_deref()
        .map(str::trim)
        .filter(|contract_id| !contract_id.is_empty())
        .map(ToOwned::to_owned);

    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::CreditCycle,
        body.dry_run,
        Some(&model_version),
        Some(body.target_use),
        Some(&policy_version),
    )
    .await?;

    let mut cycle_worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::CreditCycle,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: body.dry_run,
        reason_hash: sha256_prefixed(&reason),
        model_version: Some(model_version.clone()),
        target_use: Some(body.target_use),
        policy_version: Some(policy_version.clone()),
        limit: credit_cycle_worker_run_total_limit(&body),
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &cycle_worker_run)
        .await
        .map_err(internal_error)?;

    macro_rules! run_credit_cycle_step {
        ($step:expr, $future:expr) => {
            match $future.await {
                Ok(Json(response)) => response,
                Err(error) => {
                    cycle_worker_run.checked_count = $step;
                    let public_error = error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state.as_ref(),
                        &tenant,
                        &mut cycle_worker_run,
                        error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(error);
                }
            }
        };
    }

    let calibration = run_credit_cycle_step!(
        1,
        ranking_calibration_run_worker_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingCalibrationRunWorkerRequest {
                dry_run: body.dry_run,
                target_use: body.target_use,
                reason: reason.clone(),
                limit: body.calibration_limit,
                model_version: Some(model_version.clone()),
                policy_version: Some(policy_version.clone()),
                min_label_count: body.min_label_count,
                confidence_threshold: body.confidence_threshold,
                max_average_absolute_error_micros: body.max_average_absolute_error_micros,
            }),
        )
    );
    let model_promotion = run_credit_cycle_step!(
        2,
        ranking_model_promotion_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingModelPromotionRunRequest {
                dry_run: body.dry_run,
                target_use: body.target_use,
                reason: reason.clone(),
                limit: body.model_promotion_limit,
                model_version: Some(model_version.clone()),
                policy_version: Some(policy_version.clone()),
            }),
        )
    );
    let prediction_credit = run_credit_cycle_step!(
        3,
        ranking_prediction_credit_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceRankingPredictionCreditRunRequest {
                dry_run: body.dry_run,
                allow_at_risk_models: body.allow_at_risk_models,
                reason: reason.clone(),
                limit: body.prediction_credit_limit,
                model_version: Some(model_version.clone()),
                target_use: Some(body.target_use),
                policy_version: Some(policy_version.clone()),
            }),
        )
    );
    let settlement = run_credit_cycle_step!(
        4,
        credit_settlement_worker_run_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceCreditSettlementWorkerRunRequest {
                request: TraceCreditSettlementRunRequest {
                    dry_run: body.dry_run,
                    policy_version: policy_version.clone(),
                    reason: reason.clone(),
                    near_contract_id: near_contract_id.clone(),
                    ranking_model_version: Some(model_version.clone()),
                    ranking_target_use: Some(body.target_use),
                },
                limit: body.credit_settlement_limit,
            }),
        )
    );
    let near_outbox_submit = run_credit_cycle_step!(
        5,
        near_credit_outbox_submit_worker_handler(
            State(state.clone()),
            headers.clone(),
            Json(TraceNearCreditOutboxSubmitWorkerRequest {
                purpose: Some("trace_commons_credit_cycle_near_outbox".to_string()),
                dry_run: body.dry_run || !body.submit_near_outbox,
                limit: body
                    .near_outbox_limit
                    .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_SUBMIT_DEFAULT_LIMIT),
            }),
        )
    );
    let near_outbox_confirm = run_credit_cycle_step!(
        6,
        near_credit_outbox_confirm_worker_handler(
            State(state.clone()),
            headers,
            Json(TraceNearCreditOutboxConfirmWorkerRequest {
                purpose: Some("trace_commons_credit_cycle_near_outbox_confirm".to_string()),
                dry_run: body.dry_run || !body.confirm_near_outbox,
                limit: body
                    .near_outbox_confirm_limit
                    .or(body.near_outbox_limit)
                    .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_CONFIRM_DEFAULT_LIMIT),
            }),
        )
    );

    let response = TraceCreditCycleWorkerRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        submit_near_outbox: body.submit_near_outbox,
        confirm_near_outbox: body.confirm_near_outbox,
        target_use: body.target_use,
        model_version,
        policy_version,
        reason_hash: sha256_prefixed(&reason),
        near_contract_id,
        calibration,
        model_promotion,
        prediction_credit,
        settlement,
        near_outbox_submit,
        near_outbox_confirm,
    };
    update_credit_cycle_worker_run_from_response(&mut cycle_worker_run, &response);
    cycle_worker_run.status = TraceRankingWorkerRunStatus::Completed;
    cycle_worker_run.completed_at = Some(Utc::now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &cycle_worker_run)
        .await
        .map_err(internal_error)?;

    Ok(Json(response))
}

fn credit_cycle_worker_run_total_limit(body: &TraceCreditCycleWorkerRunRequest) -> usize {
    body.calibration_limit
        .unwrap_or(TRACE_RANKING_CALIBRATION_RUN_DEFAULT_LIMIT)
        .saturating_add(
            body.model_promotion_limit
                .unwrap_or(TRACE_RANKING_MODEL_PROMOTION_RUN_DEFAULT_LIMIT),
        )
        .saturating_add(
            body.prediction_credit_limit
                .unwrap_or(DEFAULT_RANKING_PREDICTION_CREDIT_RUN_LIMIT),
        )
        .saturating_add(
            body.credit_settlement_limit
                .unwrap_or(TRACE_CREDIT_SETTLEMENT_WORKER_RUN_DEFAULT_LIMIT),
        )
        .saturating_add(
            body.near_outbox_limit
                .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_SUBMIT_DEFAULT_LIMIT) as usize,
        )
        .saturating_add(
            body.near_outbox_confirm_limit
                .or(body.near_outbox_limit)
                .unwrap_or(TRACE_NEAR_CREDIT_OUTBOX_CONFIRM_DEFAULT_LIMIT) as usize,
        )
}

fn update_credit_cycle_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceCreditCycleWorkerRunResponse,
) {
    worker_run.checked_count = TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT;
    worker_run.succeeded_count = TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT;
    worker_run.skipped_existing_count = response.calibration.skipped_existing_count
        + response.prediction_credit.skipped_existing_count
        + response.near_outbox_submit.skipped
        + response.near_outbox_confirm.skipped;
    worker_run.skipped_model_risk_count = response.prediction_credit.skipped_model_risk_count;
    worker_run.skipped_ineligible_count = response.calibration.skipped_ineligible_count
        + response.model_promotion.skipped_ineligible_count
        + response.prediction_credit.skipped_ineligible_count;
    worker_run.pending_after_count = response.calibration.pending_after_count
        + response.model_promotion.pending_after_count
        + response.prediction_credit.pending_after_count
        + response.settlement.pending_after_count
        + response.near_outbox_submit.pending
        + response.near_outbox_confirm.pending;
    worker_run.result_refs = if response.dry_run {
        Vec::new()
    } else {
        vec![
            format!(
                "ranking_worker_run:{}",
                response.calibration.ranking_worker_run_id
            ),
            format!(
                "ranking_worker_run:{}",
                response.model_promotion.ranking_worker_run_id
            ),
            format!(
                "ranking_worker_run:{}",
                response.prediction_credit.ranking_worker_run_id
            ),
            format!(
                "credit_settlement_batch:{}",
                response.settlement.settlement_batch_id
            ),
        ]
    };
    worker_run.reason_counts = credit_cycle_worker_run_reason_counts(response);
}

fn credit_cycle_worker_run_reason_counts(
    response: &TraceCreditCycleWorkerRunResponse,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    extend_prefixed_counts(
        &mut counts,
        "calibration",
        &response.calibration.skipped_reason_counts,
    );
    extend_prefixed_counts(
        &mut counts,
        "model_promotion",
        &response.model_promotion.skipped_reason_counts,
    );
    extend_prefixed_counts(
        &mut counts,
        "model_risk",
        &response.prediction_credit.blocked_model_risk_reason_counts,
    );
    if response.near_outbox_submit.failed > 0 {
        counts.insert(
            "near_outbox_failed".to_string(),
            response.near_outbox_submit.failed,
        );
    }
    if response.near_outbox_confirm.failed > 0 {
        counts.insert(
            "near_outbox_confirm_failed".to_string(),
            response.near_outbox_confirm.failed,
        );
    }
    counts
}

fn extend_prefixed_counts(
    counts: &mut BTreeMap<String, usize>,
    prefix: &str,
    source: &BTreeMap<String, usize>,
) {
    for (reason, count) in source {
        counts.insert(format!("{prefix}:{reason}"), *count);
    }
}

async fn run_credit_settlement(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceCreditSettlementRunRequest,
    limit: Option<usize>,
) -> ApiResult<TraceCreditSettlementRunResponse> {
    let policy_version = body.policy_version.trim().to_string();
    if policy_version.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit settlement requires policy_version",
        ));
    }
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit settlement requires a non-empty reason",
        ));
    }
    let near_contract_id = body
        .near_contract_id
        .as_deref()
        .map(str::trim)
        .filter(|contract_id| !contract_id.is_empty())
        .map(ToOwned::to_owned);
    let ranking_model_version = match body.ranking_model_version.as_deref().map(str::trim) {
        Some("") => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "credit settlement ranking_model_version cannot be empty",
            ));
        }
        Some(model_version) => Some(validate_ranking_identifier(
            model_version,
            "ranking_model_version",
        )?),
        None => None,
    };
    if body.ranking_target_use.is_some() && ranking_model_version.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit settlement ranking_target_use requires ranking_model_version",
        ));
    }
    let ranking_target_use = body
        .ranking_target_use
        .unwrap_or(TraceAllowedUse::RankingModelTraining);

    let records = read_reviewer_metadata_view(state, tenant)
        .await
        .map_err(internal_error)?
        .records;
    let records_by_submission = records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let existing_batches = read_credit_settlement_batches_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    if !body.dry_run {
        let repaired_outbox_count = repair_missing_near_credit_outbox_items_for_finalized_batches(
            state,
            tenant,
            &existing_batches,
        )
        .await
        .map_err(internal_error)?;
        if repaired_outbox_count > 0 {
            tracing::warn!(
                repaired_outbox_count,
                tenant_id = %tenant.tenant_id,
                "repaired missing NEAR credit outbox items for finalized settlement batches"
            );
        }
    }
    let held_credit_accounts = active_credit_hold_account_refs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let already_settled_event_ids = existing_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
        .flat_map(|batch| batch.source_credit_event_ids.iter().copied())
        .collect::<BTreeSet<_>>();
    let credit_events = read_credit_events_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let candidate_events = credit_events
        .into_iter()
        .filter(|event| trace_credit_event_type_is_settlement_eligible(event.event_type))
        .filter(|event| event.credit_points_delta > 0.0)
        .filter(|event| !already_settled_event_ids.contains(&event.event_id))
        .filter(|event| {
            records_by_submission
                .get(&event.submission_id)
                .is_some_and(|record| {
                    record.status == TraceCorpusStatus::Accepted
                        && delayed_credit_applies_to_record(record)
                })
        })
        .filter(|event| !held_credit_accounts.contains(&event.auth_principal_ref))
        .collect::<Vec<_>>();
    let ranking_candidate_count = candidate_events
        .iter()
        .filter(|event| event.event_type == TraceCreditLedgerEventType::RankingUtility)
        .count();
    let ranking_calibration_gate = if ranking_candidate_count > 0 {
        ranking_settlement_calibration_gate(
            state,
            tenant,
            &policy_version,
            ranking_model_version.as_deref(),
            ranking_target_use,
        )
        .await?
    } else {
        None
    };
    let ranking_predictions = if ranking_candidate_count > 0 && ranking_calibration_gate.is_some() {
        read_ranking_predictions_for_admin(state, tenant)
            .await
            .map_err(internal_error)?
    } else {
        Vec::new()
    };
    let ranking_features = if ranking_candidate_count > 0
        && ranking_calibration_gate.is_some()
        && state.ranking_require_server_feature_provenance
    {
        read_ranking_features_for_admin(state, tenant)
            .await
            .map_err(internal_error)?
    } else {
        Vec::new()
    };
    let mut ranking_credit_events_excluded_count = 0usize;
    let mut ranking_credit_events_excluded_reason_counts = BTreeMap::new();
    let mut selected_events = Vec::new();
    for event in candidate_events {
        if event.event_type != TraceCreditLedgerEventType::RankingUtility {
            selected_events.push(event);
            continue;
        }
        let exclusion_reason_codes = ranking_credit_event_exclusion_reason_codes(
            state,
            &event,
            &ranking_features,
            &ranking_predictions,
            ranking_calibration_gate.as_ref(),
            &policy_version,
        );
        if exclusion_reason_codes.is_empty() {
            selected_events.push(event);
        } else {
            ranking_credit_events_excluded_count += 1;
            for code in exclusion_reason_codes {
                *ranking_credit_events_excluded_reason_counts
                    .entry(code)
                    .or_insert(0) += 1;
            }
        }
    }
    selected_events.sort_by_key(|event| event.event_id);
    let eligible_source_event_count = selected_events.len();
    if let Some(limit) = limit {
        selected_events.truncate(limit);
    }
    let pending_after_count = if body.dry_run {
        eligible_source_event_count
    } else {
        eligible_source_event_count.saturating_sub(selected_events.len())
    };

    let source_credit_event_ids = selected_events
        .iter()
        .map(|event| event.event_id)
        .collect::<Vec<_>>();
    let source_submission_ids = selected_events
        .iter()
        .map(|event| event.submission_id)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_list_hash = source_credit_event_ids_hash(&policy_version, &source_credit_event_ids);
    let settlement_batch_id = Uuid::new_v4();
    let tenant_storage_ref = tenant_storage_ref(&tenant.tenant_id);
    let reason_hash = sha256_prefixed(&reason);
    let mut grouped = BTreeMap::<String, Vec<TraceCommonsCreditLedgerRecord>>::new();
    for event in selected_events {
        grouped
            .entry(event.auth_principal_ref.clone())
            .or_default()
            .push(event);
    }

    let mut line_items = Vec::with_capacity(grouped.len());
    let mut near_outbox_items = Vec::new();
    for (credit_account_ref, events) in grouped {
        let settled_credit_micros = events
            .iter()
            .map(|event| credit_delta_micros(event.credit_points_delta))
            .sum::<i64>();
        if settled_credit_micros <= 0 {
            continue;
        }
        let source_credit_event_ids = events
            .iter()
            .map(|event| event.event_id)
            .collect::<Vec<_>>();
        let source_submission_ids = events
            .iter()
            .map(|event| event.submission_id)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        let item_source_list_hash =
            source_credit_event_ids_hash(&policy_version, &source_credit_event_ids);
        let credit_account_hash = sha256_prefixed(&credit_account_ref);
        let near_outbox_id = if near_contract_id.is_some() && !body.dry_run {
            Some(Uuid::new_v4())
        } else {
            None
        };
        let near_status = if near_contract_id.is_some() {
            StorageTraceCreditSettlementNearStatus::Pending
        } else {
            StorageTraceCreditSettlementNearStatus::Disabled
        };
        if let (Some(contract_id), Some(near_outbox_id)) = (&near_contract_id, near_outbox_id) {
            let receipt = NearCreditReceipt {
                settlement_batch_id,
                credit_account_hash: credit_account_hash.clone(),
                policy_version: policy_version.clone(),
                source_list_hash: item_source_list_hash.clone(),
                attestation_hash: sha256_prefixed(&format!(
                    "trace-credit-attestation:v1:{item_source_list_hash}"
                )),
                amount_micros: settled_credit_micros,
                issuer_signature_hash: sha256_prefixed(&format!(
                    "trace-credit-settlement:v1:{settlement_batch_id}:{item_source_list_hash}"
                )),
            };
            let near_call = NearCreditReceiptCall::settle(contract_id, receipt)
                .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?;
            near_outbox_items.push(TraceNearCreditOutboxItem {
                near_outbox_id,
                tenant_id: tenant.tenant_id.clone(),
                tenant_storage_ref: tenant_storage_ref.clone(),
                settlement_batch_id,
                credit_account_hash: credit_account_hash.clone(),
                near_call,
                status: StorageTraceCreditSettlementNearStatus::Pending,
                created_at: Utc::now(),
                submitted_at: None,
                near_transaction_hash: None,
                last_error_hash: None,
                confirmed_at: None,
            });
        }
        line_items.push(StorageTraceCreditAccountSettlementLineItem {
            credit_account_ref,
            credit_account_hash,
            settled_credit_delta_micros: settled_credit_micros,
            source_credit_event_ids,
            source_submission_ids,
            source_list_hash: item_source_list_hash,
            near_status,
            near_outbox_id,
        });
    }

    let settled_credit_micros = line_items
        .iter()
        .map(|item| item.settled_credit_delta_micros)
        .sum::<i64>();
    let settled_credit_points = settled_credit_micros as f32 / 1_000_000.0;
    if !body.dry_run && !line_items.is_empty() {
        let batch = TraceCreditSettlementBatchRecord {
            settlement_batch_id,
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref.clone(),
            policy_version: policy_version.clone(),
            status: StorageTraceCreditSettlementBatchStatus::Finalized,
            reason_hash,
            source_credit_event_ids: source_credit_event_ids.clone(),
            source_submission_ids: source_submission_ids.clone(),
            source_list_hash: source_list_hash.clone(),
            settled_credit_points,
            settled_credit_micros,
            line_items: line_items.clone(),
            near_contract_id: near_contract_id.clone(),
            ranking_model_version: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.model_version.clone()),
            ranking_target_use: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.target_use),
            ranking_calibration_run_id: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.calibration_run_id),
            ranking_calibration_report_hash: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.report_hash.clone()),
            ranking_calibration_joined_evidence_hash: ranking_calibration_gate
                .as_ref()
                .map(|gate| gate.joined_evidence_hash.clone()),
            ranking_credit_events_excluded_count,
            ranking_credit_events_excluded_reason_counts:
                ranking_credit_events_excluded_reason_counts.clone(),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        };
        append_credit_settlement_batch_with_db_mirror(state, tenant, &batch)
            .await
            .map_err(internal_error)?;
        for item in &near_outbox_items {
            append_near_credit_outbox_item_with_db_mirror(state, tenant, item)
                .await
                .map_err(internal_error)?;
        }
    }

    Ok(TraceCreditSettlementRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref,
        settlement_batch_id,
        dry_run: body.dry_run,
        policy_version,
        source_list_hash,
        limit,
        settled_source_event_count: source_credit_event_ids.len(),
        eligible_source_event_count,
        pending_after_count,
        settled_account_count: line_items.len(),
        settled_credit_points,
        near_outbox_item_count: near_outbox_items.len(),
        ranking_model_version: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.model_version.clone()),
        ranking_target_use: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.target_use),
        ranking_calibration_run_id: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.calibration_run_id),
        ranking_calibration_report_hash: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.report_hash.clone()),
        ranking_calibration_joined_evidence_hash: ranking_calibration_gate
            .as_ref()
            .map(|gate| gate.joined_evidence_hash.clone()),
        ranking_credit_events_excluded_count,
        ranking_credit_events_excluded_reason_counts,
    })
}

fn validate_credit_settlement_run_limit(limit: Option<usize>) -> ApiResult<Option<usize>> {
    if let Some(limit) = limit {
        if !(1..=TRACE_CREDIT_SETTLEMENT_WORKER_RUN_MAX_LIMIT).contains(&limit) {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "credit settlement run limit must be between 1 and 500",
            ));
        }
        Ok(Some(limit))
    } else {
        Ok(None)
    }
}

async fn repair_missing_near_credit_outbox_items_for_finalized_batches(
    state: &AppState,
    tenant: &TenantAuth,
    settlement_batches: &[TraceCreditSettlementBatchRecord],
) -> anyhow::Result<usize> {
    if !settlement_batches.iter().any(|batch| {
        batch.status == StorageTraceCreditSettlementBatchStatus::Finalized
            && batch.near_contract_id.is_some()
            && batch
                .line_items
                .iter()
                .any(|item| item.near_outbox_id.is_some())
    }) {
        return Ok(0);
    }

    let mut existing_outbox_ids = read_near_credit_outbox_items_for_admin(state, tenant)
        .await?
        .into_iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    let mut repaired = 0usize;
    for batch in settlement_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
    {
        let Some(contract_id) = batch.near_contract_id.as_deref() else {
            continue;
        };
        for item in &batch.line_items {
            let Some(near_outbox_id) = item.near_outbox_id else {
                continue;
            };
            if existing_outbox_ids.contains(&near_outbox_id) {
                continue;
            }
            let outbox_item = near_credit_outbox_item_from_settlement_line_item(
                tenant,
                batch,
                item,
                contract_id,
                near_outbox_id,
            )?;
            append_near_credit_outbox_item_with_db_mirror(state, tenant, &outbox_item).await?;
            existing_outbox_ids.insert(near_outbox_id);
            repaired += 1;
        }
    }
    Ok(repaired)
}

fn near_credit_outbox_item_from_settlement_line_item(
    tenant: &TenantAuth,
    batch: &TraceCreditSettlementBatchRecord,
    item: &StorageTraceCreditAccountSettlementLineItem,
    contract_id: &str,
    near_outbox_id: Uuid,
) -> anyhow::Result<TraceNearCreditOutboxItem> {
    let receipt = NearCreditReceipt {
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        policy_version: batch.policy_version.clone(),
        source_list_hash: item.source_list_hash.clone(),
        attestation_hash: sha256_prefixed(&format!(
            "trace-credit-attestation:v1:{}",
            item.source_list_hash
        )),
        amount_micros: item.settled_credit_delta_micros,
        issuer_signature_hash: sha256_prefixed(&format!(
            "trace-credit-settlement:v1:{}:{}",
            batch.settlement_batch_id, item.source_list_hash
        )),
    };
    let near_call = NearCreditReceiptCall::settle(contract_id, receipt)?;
    Ok(TraceNearCreditOutboxItem {
        near_outbox_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        near_call,
        status: StorageTraceCreditSettlementNearStatus::Pending,
        created_at: batch.created_at,
        submitted_at: None,
        near_transaction_hash: None,
        last_error_hash: None,
        confirmed_at: None,
    })
}

fn near_credit_reversal_outbox_item_from_settled_credit_event(
    tenant_id: &str,
    batch: &TraceCreditSettlementBatchRecord,
    item: &StorageTraceCreditAccountSettlementLineItem,
    source_event: &StorageTraceCreditEventRecord,
    contract_id: &str,
    near_outbox_id: Uuid,
) -> anyhow::Result<TraceNearCreditOutboxItem> {
    let source_event_points = source_event.points_delta.parse::<f32>().with_context(|| {
        format!(
            "failed to parse settled trace credit points_delta for event {}",
            source_event.credit_event_id
        )
    })?;
    anyhow::ensure!(
        source_event_points.is_finite() && source_event_points > 0.0,
        "NEAR credit reversal requires a positive settled credit event"
    );
    let source_list_hash =
        source_credit_event_ids_hash(&batch.policy_version, &[source_event.credit_event_id]);
    let amount_micros = credit_delta_micros(source_event_points);
    let receipt = NearCreditReceipt {
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        policy_version: batch.policy_version.clone(),
        source_list_hash: source_list_hash.clone(),
        attestation_hash: sha256_prefixed(&format!(
            "trace-credit-reversal-attestation:v1:{source_list_hash}"
        )),
        amount_micros,
        issuer_signature_hash: sha256_prefixed(&format!(
            "trace-credit-reversal:v1:{}:{}:{}",
            batch.settlement_batch_id, source_event.credit_event_id, source_list_hash
        )),
    };
    let near_call = NearCreditReceiptCall::reverse(contract_id, receipt)?;
    Ok(TraceNearCreditOutboxItem {
        near_outbox_id,
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        settlement_batch_id: batch.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        near_call,
        status: StorageTraceCreditSettlementNearStatus::Pending,
        created_at: Utc::now(),
        submitted_at: None,
        near_transaction_hash: None,
        last_error_hash: None,
        confirmed_at: None,
    })
}

