async fn ranking_model_version_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingModelVersionRequest>,
) -> ApiResult<Json<TraceRankingModelVersionRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let feature_schema_version =
        validate_ranking_identifier(&body.feature_schema_version, "feature_schema_version")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let training_dataset_hash =
        validate_sha256_hash(&body.training_dataset_hash, "training_dataset_hash")?;
    let calibration_dataset_hash =
        validate_sha256_hash(&body.calibration_dataset_hash, "calibration_dataset_hash")?;
    ensure_ranking_model_dataset_hashes_are_disjoint(
        &training_dataset_hash,
        &calibration_dataset_hash,
        RankingModelDatasetIsolationContext::Registration,
    )?;
    let model_artifact_hash =
        validate_sha256_hash(&body.model_artifact_hash, "model_artifact_hash")?;
    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if let Some(existing) = latest_ranking_model_version(&model_versions, &model_version) {
        let manifest_matches = existing.feature_schema_version == feature_schema_version
            && existing.policy_version == policy_version
            && existing.training_dataset_hash == training_dataset_hash
            && existing.calibration_dataset_hash == calibration_dataset_hash
            && existing.model_artifact_hash == model_artifact_hash;
        if !manifest_matches {
            return Err(api_error(
                StatusCode::CONFLICT,
                "ranking model version manifest is immutable; register a new model_version for changed schema, policy, dataset, or artifact hashes",
            ));
        }
    }
    if body.status == StorageTraceRankingModelStatus::Active {
        return Err(api_error(
            StatusCode::CONFLICT,
            "active ranking model registration is target-use scoped; register a candidate and use /v1/admin/ranking/model-promotions",
        ));
    }

    let record = TraceRankingModelVersionRecord {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        model_version,
        feature_schema_version,
        policy_version,
        status: body.status,
        training_dataset_hash,
        calibration_dataset_hash,
        model_artifact_hash,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_model_version_with_db_mirror(state.as_ref(), &tenant, &record)
        .await
        .map_err(internal_error)?;
    Ok(Json(record))
}

