async fn ranking_calibration_dataset_conflict_quarantine_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingCalibrationDatasetConflictQuarantineRequest>,
) -> ApiResult<Json<TraceRankingCalibrationDatasetConflictQuarantineResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let calibration_dataset_hash =
        validate_sha256_hash(&body.calibration_dataset_hash, "calibration_dataset_hash")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let reason = validate_ranking_calibration_dataset_conflict_quarantine_reason(&body.reason)?;
    let reason_hash = sha256_prefixed(&reason);
    let conflict_key = ranking_calibration_dataset_key(
        &calibration_dataset_hash,
        body.target_use,
        &policy_version,
    )
    .map_err(internal_error)?;
    let read = read_ranking_calibration_datasets_for_admin_reconciliation(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if !read.manifest_conflict_keys.contains(&conflict_key) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking calibration dataset conflict is not active for this key",
        ));
    }
    let latest = read
        .records
        .iter()
        .find(|record| {
            record.calibration_dataset_hash == calibration_dataset_hash
                && record.target_use == body.target_use
                && record.policy_version == policy_version
        })
        .ok_or_else(|| {
            api_error(
                StatusCode::NOT_FOUND,
                "ranking calibration dataset conflict key was not found",
            )
        })?;
    let archived_record = TraceRankingCalibrationDatasetRecord {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        calibration_dataset_hash,
        target_use: body.target_use,
        policy_version,
        source_manifest_hash: latest.source_manifest_hash.clone(),
        source_count: latest.source_count,
        label_source_count: latest.label_source_count,
        label_actor_count: latest.label_actor_count,
        status: StorageTraceRankingCalibrationDatasetStatus::Archived,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_calibration_dataset_status_override_with_db_mirror(
        state.as_ref(),
        &tenant,
        &archived_record,
    )
    .await
    .map_err(internal_error)?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::ranking_calibration_dataset_quarantine(
            &tenant,
            &archived_record,
            &conflict_key,
            &reason_hash,
        ),
        StorageTraceAuditAction::RankingCalibrationDatasetQuarantine,
        ranking_calibration_dataset_quarantine_audit_metadata(
            &archived_record,
            &conflict_key,
            &reason_hash,
        )
        .map_err(internal_error)?,
    )
    .await
    .map_err(internal_error)?;
    let remaining_conflict_count =
        read_ranking_calibration_datasets_for_admin_reconciliation(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?
            .manifest_conflict_keys
            .len();
    Ok(Json(
        TraceRankingCalibrationDatasetConflictQuarantineResponse {
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            conflict_key,
            reason_hash,
            archived_record,
            remaining_conflict_count,
        },
    ))
}

fn validate_ranking_calibration_dataset_conflict_quarantine_reason(
    reason: &str,
) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration dataset conflict quarantine requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration dataset conflict quarantine reason is too long",
        ));
    }
    Ok(reason)
}

fn ranking_calibration_dataset_quarantine_decision_hash(
    conflict_key: &str,
    reason_hash: &str,
    archived_source_manifest_hash: &str,
) -> String {
    sha256_prefixed(&format!(
        "{conflict_key}\n{reason_hash}\n{archived_source_manifest_hash}"
    ))
}

fn ranking_calibration_dataset_quarantine_audit_metadata(
    record: &TraceRankingCalibrationDatasetRecord,
    conflict_key: &str,
    reason_hash: &str,
) -> anyhow::Result<StorageTraceAuditSafeMetadata> {
    Ok(
        StorageTraceAuditSafeMetadata::RankingCalibrationDatasetQuarantine {
            calibration_dataset_hash: record.calibration_dataset_hash.clone(),
            target_use: serde_storage_string(&record.target_use)?,
            policy_version: record.policy_version.clone(),
            archived_source_manifest_hash: record.source_manifest_hash.clone(),
            conflict_key_hash: sha256_prefixed(conflict_key),
            reason_hash: reason_hash.to_string(),
        },
    )
}

fn ranking_calibration_dataset_conflict_report(
    tenant: &TenantAuth,
    read: RankingCalibrationDatasetReconciliationRead,
) -> TraceRankingCalibrationDatasetConflictReport {
    let records_by_key = read
        .records
        .iter()
        .filter_map(|record| {
            ranking_calibration_dataset_file_key(record)
                .ok()
                .map(|key| (key, record))
        })
        .collect::<BTreeMap<_, _>>();
    let mut conflicts = read
        .manifest_conflict_keys
        .iter()
        .filter_map(|conflict_key| {
            let latest = records_by_key.get(conflict_key)?;
            Some(TraceRankingCalibrationDatasetConflictRecord {
                conflict_key: conflict_key.clone(),
                calibration_dataset_hash: latest.calibration_dataset_hash.clone(),
                target_use: latest.target_use,
                policy_version: latest.policy_version.clone(),
                latest_source_manifest_hash: latest.source_manifest_hash.clone(),
                latest_source_count: latest.source_count,
                latest_label_source_count: latest.label_source_count,
                latest_label_actor_count: latest.label_actor_count,
                latest_status: latest.status,
                latest_created_at: latest.created_at,
                blocks_credit_issuance: !ranking_calibration_dataset_status_is_retired(
                    latest.status,
                ),
                recommended_action:
                    "register a new calibration_dataset_hash or policy_version after choosing the canonical source manifest; do not rewrite this conflicted key"
                        .to_string(),
            })
        })
        .collect::<Vec<_>>();
    conflicts.sort_by(|left, right| left.conflict_key.cmp(&right.conflict_key));
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| conflict.conflict_key.clone())
        .collect::<Vec<_>>();
    TraceRankingCalibrationDatasetConflictReport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        conflict_count: conflicts.len(),
        conflict_keys,
        conflicts,
    }
}

