async fn ranking_prediction_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionRequest>,
) -> ApiResult<Json<TraceRankingPredictionRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let submission = read_ranking_source_submission(
        state.as_ref(),
        &tenant,
        body.submission_id,
        body.target_use,
    )
    .await?;
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let feature_schema_version =
        validate_ranking_identifier(&body.feature_schema_version, "feature_schema_version")?;
    let prediction_policy_version =
        validate_ranking_identifier(&body.prediction_policy_version, "prediction_policy_version")?;
    let feature_vector_hash =
        validate_sha256_hash(&body.feature_vector_hash, "feature_vector_hash")?;
    validate_nonnegative_micros(body.predicted_utility_micros, "predicted_utility_micros")?;
    validate_nonnegative_micros(body.uncertainty_micros, "uncertainty_micros")?;
    validate_unit_score(body.confidence, "confidence")?;
    validate_nonnegative_micros(body.risk_penalty_micros, "risk_penalty_micros")?;
    validate_nonnegative_micros(body.novelty_bonus_micros, "novelty_bonus_micros")?;
    validate_ranking_codes(&body.explanation_codes, "explanation_codes")?;
    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &model_version).ok_or_else(|| {
        api_error(
            StatusCode::NOT_FOUND,
            "ranking prediction model version not found",
        )
    })?;
    ensure_ranking_model_accepts_evidence(model)?;
    if model.feature_schema_version != feature_schema_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction feature schema does not match the registered model",
        ));
    }
    if model.policy_version != prediction_policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction policy does not match the registered model",
        ));
    }
    let features = read_ranking_features_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if !features.iter().any(|feature| {
        feature.submission_id == submission.submission_id
            && feature.target_use == body.target_use
            && feature.feature_schema_version == feature_schema_version
            && feature.feature_vector_hash == feature_vector_hash
    }) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction must reference an existing feature vector for the source and model schema",
        ));
    }

    let settlement_score_micros =
        body.predicted_utility_micros + body.novelty_bonus_micros - body.risk_penalty_micros;
    let record = TraceRankingPredictionRecord {
        ranking_prediction_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id: submission.submission_id,
        trace_id: submission.trace_id,
        target_use: body.target_use,
        model_version,
        feature_schema_version,
        prediction_policy_version,
        feature_vector_hash,
        predicted_utility_micros: body.predicted_utility_micros,
        uncertainty_micros: body.uncertainty_micros,
        confidence: body.confidence,
        risk_penalty_micros: body.risk_penalty_micros,
        novelty_bonus_micros: body.novelty_bonus_micros,
        settlement_score_micros,
        explanation_codes: body.explanation_codes,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_prediction_with_db_mirror(state.as_ref(), &tenant, &record)
        .await
        .map_err(internal_error)?;
    Ok(Json(record))
}

async fn ranking_prediction_credit_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionCreditRequest>,
) -> ApiResult<Json<TraceRankingPredictionCreditResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_prediction_credit_reason(&body.reason)?;

    let predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let prediction = predictions
        .into_iter()
        .find(|prediction| prediction.ranking_prediction_id == body.ranking_prediction_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking prediction not found"))?;
    append_ranking_prediction_credit_for_record(
        state.as_ref(),
        &tenant,
        prediction,
        &reason,
        false,
        false,
    )
    .await
    .map(Json)
}

async fn ranking_prediction_credit_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionCreditRunRequest>,
) -> ApiResult<Json<TraceRankingPredictionCreditRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_prediction_credit_reason(&body.reason)?;
    let limit = body
        .limit
        .unwrap_or(DEFAULT_RANKING_PREDICTION_CREDIT_RUN_LIMIT);
    if !(1..=MAX_RANKING_PREDICTION_CREDIT_RUN_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit run limit must be between 1 and 500",
        ));
    }
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::PredictionCredit,
        body.dry_run,
        model_version.as_deref(),
        body.target_use,
        policy_version.as_deref(),
    )
    .await?;
    let mut predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    predictions.sort_by_key(|prediction| {
        (
            prediction.created_at,
            prediction.submission_id,
            prediction.ranking_prediction_id,
        )
    });
    let blocked_model_risk_codes_by_key = if body.allow_at_risk_models {
        BTreeMap::new()
    } else {
        let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let labels = read_ranking_labels_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let preference_labels = read_ranking_preference_labels_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let calibration_datasets =
            read_ranking_calibration_datasets_for_admin(state.as_ref(), &tenant)
                .await
                .map_err(internal_error)?;
        let calibration_runs = read_ranking_calibration_runs_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        blocking_ranking_model_risk_codes_by_key(ranking_model_risk_report(
            state.as_ref(),
            &tenant,
            &model_versions,
            RankingModelRiskEvidence {
                predictions: &predictions,
                labels: &labels,
                preference_labels: &preference_labels,
                calibration_datasets: &calibration_datasets,
                calibration_runs: &calibration_runs,
            },
        ))
    };
    let mut response = TraceRankingPredictionCreditRunResponse {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        allow_at_risk_models: body.allow_at_risk_models,
        limit,
        reason_hash: sha256_prefixed(&reason),
        model_version: model_version.clone(),
        target_use: body.target_use,
        policy_version: policy_version.clone(),
        checked_count: 0,
        credited_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        blocked_model_risk_reason_counts: BTreeMap::new(),
        pending_after_count: 0,
    };
    let mut worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: response.ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::PredictionCredit,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: response.dry_run,
        reason_hash: response.reason_hash.clone(),
        model_version: response.model_version.clone(),
        target_use: response.target_use,
        policy_version: response.policy_version.clone(),
        limit: response.limit,
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    let mut attempted_uncredited = 0;
    let mut result_refs = Vec::new();
    for prediction in predictions.into_iter().filter(|prediction| {
        model_version
            .as_ref()
            .is_none_or(|model_version| &prediction.model_version == model_version)
            && body
                .target_use
                .is_none_or(|target_use| prediction.target_use == target_use)
            && policy_version.as_ref().is_none_or(|policy_version| {
                &prediction.prediction_policy_version == policy_version
            })
    }) {
        let already_credited =
            match ranking_prediction_credit_already_exists(state.as_ref(), &tenant, &prediction)
                .await
            {
                Ok(already_credited) => already_credited,
                Err(error) => {
                    let api_error = internal_error(error);
                    update_prediction_credit_worker_run_from_response(
                        &mut worker_run,
                        &response,
                        &result_refs,
                    );
                    let public_error = api_error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state.as_ref(),
                        &tenant,
                        &mut worker_run,
                        api_error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(api_error);
                }
            };
        if already_credited {
            response.checked_count += 1;
            response.skipped_existing_count += 1;
            continue;
        }
        if attempted_uncredited >= limit {
            break;
        }
        response.checked_count += 1;
        attempted_uncredited += 1;
        if let Some(risk_codes) =
            blocked_model_risk_codes_by_key.get(&ranking_prediction_risk_lookup_key(&prediction))
        {
            response.skipped_model_risk_count += 1;
            for code in risk_codes {
                *response
                    .blocked_model_risk_reason_counts
                    .entry(code.clone())
                    .or_insert(0) += 1;
            }
            continue;
        }
        let result_ref = ranking_prediction_external_ref(prediction.ranking_prediction_id);
        match append_ranking_prediction_credit_for_record(
            state.as_ref(),
            &tenant,
            prediction,
            &reason,
            body.dry_run,
            true,
        )
        .await
        {
            Ok(credit) => {
                if credit.appended_count > 0 {
                    result_refs.push(result_ref);
                }
                response.credited_count += credit.appended_count;
                response.skipped_existing_count += credit.skipped_existing_count;
            }
            Err((status, _)) if ranking_prediction_credit_run_can_skip_status(status) => {
                response.skipped_ineligible_count += 1;
            }
            Err(error) => {
                update_prediction_credit_worker_run_from_response(
                    &mut worker_run,
                    &response,
                    &result_refs,
                );
                let public_error = error.1.0.error.clone();
                finalize_failed_ranking_worker_run_with_db_mirror(
                    state.as_ref(),
                    &tenant,
                    &mut worker_run,
                    error.0,
                    &public_error,
                )
                .await?;
                return Err(error);
            }
        }
    }
    response.pending_after_count = match count_pending_ranking_prediction_credits(
        state.as_ref(),
        &tenant,
        model_version.as_deref(),
        body.target_use,
        policy_version.as_deref(),
    )
    .await
    {
        Ok(pending_after_count) => pending_after_count,
        Err(error) => {
            let api_error = internal_error(error);
            update_prediction_credit_worker_run_from_response(
                &mut worker_run,
                &response,
                &result_refs,
            );
            let public_error = api_error.1.0.error.clone();
            finalize_failed_ranking_worker_run_with_db_mirror(
                state.as_ref(),
                &tenant,
                &mut worker_run,
                api_error.0,
                &public_error,
            )
            .await?;
            return Err(api_error);
        }
    };
    update_prediction_credit_worker_run_from_response(&mut worker_run, &response, &result_refs);
    worker_run.status = TraceRankingWorkerRunStatus::Completed;
    worker_run.completed_at = Some(Utc::now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;
    Ok(Json(response))
}

fn validate_ranking_prediction_credit_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit jobs require a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit reason is too long",
        ));
    }
    Ok(reason)
}

fn optional_ranking_identifier(value: Option<String>, label: &str) -> ApiResult<Option<String>> {
    value
        .map(|value| validate_ranking_identifier(&value, label))
        .transpose()
}

fn ranking_prediction_credit_run_can_skip_status(status: StatusCode) -> bool {
    matches!(
        status,
        StatusCode::BAD_REQUEST | StatusCode::NOT_FOUND | StatusCode::CONFLICT
    )
}

fn update_prediction_credit_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceRankingPredictionCreditRunResponse,
    result_refs: &[String],
) {
    worker_run.checked_count = response.checked_count;
    worker_run.succeeded_count = response.credited_count;
    worker_run.skipped_existing_count = response.skipped_existing_count;
    worker_run.skipped_model_risk_count = response.skipped_model_risk_count;
    worker_run.skipped_ineligible_count = response.skipped_ineligible_count;
    worker_run.pending_after_count = response.pending_after_count;
    worker_run.result_refs = result_refs.to_vec();
    worker_run.reason_counts = response.blocked_model_risk_reason_counts.clone();
}

fn ranking_worker_run_error_hash(http_status: StatusCode, public_error: &str) -> String {
    sha256_prefixed(&format!(
        "status={};error={public_error}",
        http_status.as_u16()
    ))
}

fn ranking_worker_run_recovery_error_hash(reason: &str) -> String {
    sha256_prefixed(&format!(
        "status=409;error=stale_ranking_worker_run_recovered;reason_hash={}",
        sha256_prefixed(reason)
    ))
}

fn ranking_worker_run_recovery_audit_reason(
    ranking_worker_run_id: Uuid,
    run_kind: StorageTraceRankingWorkerRunKind,
    status: StorageTraceRankingWorkerRunStatus,
    reason_hash: &str,
) -> String {
    format!(
        "ranking_worker_run_id={ranking_worker_run_id};run_kind={};status={};reason_hash={reason_hash}",
        serde_enum_tag(&run_kind),
        serde_enum_tag(&status)
    )
}

fn ranking_worker_run_recovery_audit_metadata(
    record: &TraceRankingWorkerRunRecord,
    reason_hash: &str,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::RankingWorkerRunRecovery {
        ranking_worker_run_id: record.ranking_worker_run_id,
        run_kind: record.run_kind,
        recovered_status: record.status,
        reason_hash: reason_hash.to_string(),
    }
}

async fn finalize_failed_ranking_worker_run_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    worker_run: &mut TraceRankingWorkerRunRecord,
    http_status: StatusCode,
    public_error: &str,
) -> ApiResult<()> {
    worker_run.status = TraceRankingWorkerRunStatus::Failed;
    worker_run.completed_at = Some(Utc::now());
    worker_run.last_error_hash = Some(ranking_worker_run_error_hash(http_status, public_error));
    append_ranking_worker_run_with_db_mirror(state, tenant, worker_run)
        .await
        .map_err(internal_error)
}

fn ranking_prediction_credit_event_id(
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> Uuid {
    deterministic_trace_uuid_for_external_ref(
        TraceCreditLedgerEventType::RankingUtility.utility_idempotency_label(),
        &tenant.tenant_id,
        prediction.submission_id,
        &ranking_prediction_external_ref(prediction.ranking_prediction_id),
    )
}

async fn ranking_prediction_credit_already_exists(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> anyhow::Result<bool> {
    let event_id = ranking_prediction_credit_event_id(tenant, prediction);
    Ok(read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .any(|event| event.event_id == event_id))
}

async fn count_pending_ranking_prediction_credits(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
) -> anyhow::Result<usize> {
    let predictions = read_ranking_predictions_for_admin(state, tenant).await?;
    let existing_event_ids = read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    Ok(predictions
        .iter()
        .filter(|prediction| {
            prediction.settlement_score_micros > 0
                && model_version
                    .is_none_or(|model_version| prediction.model_version == model_version)
                && target_use.is_none_or(|target_use| prediction.target_use == target_use)
                && policy_version.is_none_or(|policy_version| {
                    prediction.prediction_policy_version == policy_version
                })
                && !existing_event_ids
                    .contains(&ranking_prediction_credit_event_id(tenant, prediction))
        })
        .count())
}

async fn ranking_prediction_model_risk_codes(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> ApiResult<Vec<String>> {
    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let risk_key = ranking_prediction_risk_lookup_key(prediction);
    Ok(ranking_model_risk_report(
        state,
        tenant,
        &model_versions,
        RankingModelRiskEvidence {
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_runs: &calibration_runs,
        },
    )
    .models
    .into_iter()
    .find(|model| {
        ranking_model_risk_lookup_key(
            &model.model_version,
            model.target_use,
            &model.policy_version,
        ) == risk_key
    })
    .map(|model| model.risk_codes)
    .unwrap_or_default())
}

async fn append_ranking_prediction_credit_for_record(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: TraceRankingPredictionRecord,
    reason: &str,
    dry_run: bool,
    allow_at_risk_model: bool,
) -> ApiResult<TraceRankingPredictionCreditResponse> {
    if prediction.settlement_score_micros <= 0 {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires a positive settlement score",
        ));
    }

    let submission = read_ranking_source_submission(
        state,
        tenant,
        prediction.submission_id,
        prediction.target_use,
    )
    .await?;
    if submission.trace_id != prediction.trace_id {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit source does not match the referenced trace",
        ));
    }

    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &prediction.model_version)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking prediction model not found"))?;
    if model.status != StorageTraceRankingModelStatus::Active {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires an active model version",
        ));
    }
    ensure_ranking_model_dataset_isolation(
        model,
        RankingModelDatasetIsolationContext::PredictionCredit,
    )?;
    if model.feature_schema_version != prediction.feature_schema_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit feature schema does not match the active model",
        ));
    }
    if model.policy_version != prediction.prediction_policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit policy does not match the active model",
        ));
    }
    if state.ranking_require_server_feature_provenance {
        let features = read_ranking_features_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        if !ranking_prediction_has_server_feature_provenance(&features, &prediction) {
            return Err(api_error(
                StatusCode::CONFLICT,
                "ranking prediction credit requires server-provenanced ranking feature evidence",
            ));
        }
    }
    let calibration_run = latest_promotable_ranking_calibration_run(
        state,
        tenant,
        &prediction.model_version,
        prediction.target_use,
        &prediction.prediction_policy_version,
        &model.calibration_dataset_hash,
        RankingCalibrationGateContext::PredictionCredit,
    )
    .await?;
    let calibration_thresholds =
        effective_ranking_calibration_thresholds(state, Some(&calibration_run));
    if prediction.confidence < calibration_thresholds.confidence_threshold {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires prediction confidence to meet the calibration threshold",
        ));
    }
    if !allow_at_risk_model {
        let risk_codes = ranking_prediction_model_risk_codes(state, tenant, &prediction).await?;
        if !risk_codes.is_empty() {
            return Err(api_error(
                StatusCode::CONFLICT,
                format!(
                    "ranking prediction credit requires model risk to be clear: {}",
                    risk_codes.join(",")
                ),
            ));
        }
    }

    let credit_points_delta = prediction.settlement_score_micros as f32 / 1_000_000.0;
    if !credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit delta must be finite",
        ));
    }
    if credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit exceeds the delayed credit policy limit",
        ));
    }

    let external_ref = ranking_prediction_external_ref(prediction.ranking_prediction_id);
    let counts = if dry_run {
        AutomaticUtilityCreditAppendCounts::default()
    } else {
        append_automatic_utility_credit_events_once_with_counts(
            state,
            tenant,
            AutomaticUtilityCreditConfig {
                idempotency_label: TraceCreditLedgerEventType::RankingUtility
                    .utility_idempotency_label(),
                idempotency_ref: Some(external_ref.clone()),
                event_type: TraceCreditLedgerEventType::RankingUtility,
                credit_points_delta,
                reason: format!("ranking prediction credit: {reason}"),
                external_ref: external_ref.clone(),
            },
            [AutomaticUtilityCreditSource {
                submission_id: submission.submission_id,
                trace_id: submission.trace_id,
                auth_principal_ref: submission.auth_principal_ref,
            }],
        )
        .await
        .map_err(internal_error)?
    };

    Ok(TraceRankingPredictionCreditResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        ranking_prediction_id: prediction.ranking_prediction_id,
        submission_id: prediction.submission_id,
        model_version: prediction.model_version,
        target_use: prediction.target_use,
        policy_version: prediction.prediction_policy_version,
        credit_points_delta,
        external_ref,
        appended_count: counts.appended,
        skipped_existing_count: counts.skipped_existing,
    })
}

