async fn export_jobs_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ExportJobsQuery>,
) -> ApiResult<Json<Vec<TraceExportJobSummary>>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let db = trace_export_control_db(state.as_ref())?;
    let limit = query.limit.unwrap_or(100).clamp(1, 500);
    let dataset_kind = query
        .dataset_kind
        .as_deref()
        .map(normalized_export_dataset_kind_filter);
    let jobs = db
        .list_trace_export_jobs(&tenant.tenant_id)
        .await
        .map_err(internal_error)?;
    let summaries = jobs
        .into_iter()
        .rev()
        .filter(|job| query.status.is_none_or(|status| job.status == status))
        .filter(|job| {
            dataset_kind
                .as_deref()
                .is_none_or(|dataset_kind| job.requested_dataset_kind == dataset_kind)
        })
        .take(limit)
        .map(TraceExportJobSummary::from_storage_record)
        .collect::<Vec<_>>();
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "export_jobs", summaries.len()),
        StorageTraceAuditAction::Read,
        StorageTraceAuditSafeMetadata::Empty,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(summaries))
}

async fn operational_summary_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<TraceOperationalSummaryResponse>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(tenant.auth())?;
    let generated_at = Utc::now();
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let credit_events = read_operational_credit_events(state.as_ref(), tenant.auth(), &records)
        .await
        .map_err(internal_error)?;
    let db_summary = read_operational_db_summary(state.as_ref(), tenant.auth())
        .await
        .map_err(internal_error)?;
    let ranking = read_operational_ranking_summary(
        state.as_ref(),
        tenant.auth(),
        &credit_events,
        generated_at,
    )
    .await
    .map_err(internal_error)?;
    let benchmark_artifacts =
        list_benchmark_conversion_artifacts_for_worker(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let benchmark_registry_outbox =
        read_benchmark_registry_outbox_items_for_admin(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let response = TraceOperationalSummaryResponse::from_parts(TraceOperationalSummaryInputs {
        state: state.as_ref(),
        tenant_id: tenant.tenant_id().to_string(),
        records,
        derived,
        credit_events,
        db_summary,
        benchmark_artifacts,
        benchmark_registry_outbox,
        ranking,
        generated_at,
    });
    append_audit_event_with_db_mirror(
        state.as_ref(),
        tenant.auth(),
        tenant.read_audit_event("operational_summary", response.submissions.total),
        StorageTraceAuditAction::Read,
        StorageTraceAuditSafeMetadata::Empty,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(response))
}

fn normalized_export_dataset_kind_filter(value: &str) -> String {
    value.trim().replace('-', "_")
}

async fn read_operational_credit_events(
    state: &AppState,
    tenant: &TenantAuth,
    records: &[TraceCommonsSubmissionRecord],
) -> anyhow::Result<Vec<TraceCommonsCreditLedgerRecord>> {
    if state.db_contributor_reads_for_tenant(&tenant.tenant_id) {
        return read_contributor_credit_events_from_db(state, tenant, records).await;
    }

    Ok(credit_events_for_records(
        records,
        visible_credit_events(
            tenant,
            read_all_credit_events(&state.root, &tenant.tenant_id)?,
        ),
    ))
}

async fn read_operational_ranking_summary(
    state: &AppState,
    tenant: &TenantAuth,
    credit_events: &[TraceCommonsCreditLedgerRecord],
    generated_at: DateTime<Utc>,
) -> anyhow::Result<TraceOperationalRankingSummary> {
    let settlement_batches = read_credit_settlement_batches_for_admin(state, tenant).await?;
    let held_credit_accounts = active_credit_hold_account_refs_for_admin(state, tenant).await?;
    let model_versions = read_ranking_model_versions_for_admin(state, tenant).await?;
    let features = read_ranking_features_for_admin(state, tenant).await?;
    let predictions = read_ranking_predictions_for_admin(state, tenant).await?;
    let labels = read_ranking_labels_for_admin(state, tenant).await?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant).await?;
    let calibration_dataset_read =
        read_ranking_calibration_datasets_for_admin_reconciliation(state, tenant).await?;
    let calibration_dataset_manifest_conflict_count =
        calibration_dataset_read.manifest_conflict_keys.len();
    let calibration_datasets = calibration_dataset_read.records;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant).await?;
    let worker_runs = read_ranking_worker_runs_for_admin(state, tenant).await?;
    Ok(TraceOperationalRankingSummary::from_inputs(
        TraceOperationalRankingInputs {
            state,
            tenant,
            credit_events,
            settlement_batches: &settlement_batches,
            held_credit_accounts: &held_credit_accounts,
            model_versions: &model_versions,
            features: &features,
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_dataset_manifest_conflict_count,
            calibration_runs: &calibration_runs,
            worker_runs: &worker_runs,
            generated_at,
        },
    ))
}

#[derive(Debug, Default)]
struct TraceOperationalDbSummary {
    db_available: bool,
    export_manifests: Vec<StorageTraceExportManifestRecord>,
    export_jobs: Vec<StorageTraceExportJobRecord>,
    retention_jobs: Vec<StorageTraceRetentionJobRecord>,
    vector_entries: Vec<StorageTraceVectorEntryRecord>,
}

async fn read_operational_db_summary(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<TraceOperationalDbSummary> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(TraceOperationalDbSummary::default());
    };
    let tenant_id = &tenant.tenant_id;
    Ok(TraceOperationalDbSummary {
        db_available: true,
        export_manifests: db
            .list_trace_export_manifests(tenant_id)
            .await
            .context("failed to read Trace Commons operational export manifests")?,
        export_jobs: db
            .list_trace_export_jobs(tenant_id)
            .await
            .context("failed to read Trace Commons operational export jobs")?,
        retention_jobs: db
            .list_trace_retention_jobs(tenant_id)
            .await
            .context("failed to read Trace Commons operational retention jobs")?,
        vector_entries: db
            .list_trace_vector_entries(tenant_id)
            .await
            .context("failed to read Trace Commons operational vector entries")?,
    })
}

fn trace_operational_artifact_kind_name(kind: StorageTraceObjectArtifactKind) -> &'static str {
    match kind {
        StorageTraceObjectArtifactKind::SubmittedEnvelope => "submitted_envelope",
        StorageTraceObjectArtifactKind::RescrubbedEnvelope => "rescrubbed_envelope",
        StorageTraceObjectArtifactKind::ReviewSnapshot => "review_snapshot",
        StorageTraceObjectArtifactKind::BenchmarkArtifact => "benchmark_artifact",
        StorageTraceObjectArtifactKind::ExportArtifact => "export_artifact",
        StorageTraceObjectArtifactKind::WorkerIntermediate => "worker_intermediate",
    }
}

fn trace_operational_export_job_status_name(status: StorageTraceExportJobStatus) -> &'static str {
    match status {
        StorageTraceExportJobStatus::Queued => "queued",
        StorageTraceExportJobStatus::Running => "running",
        StorageTraceExportJobStatus::Complete => "complete",
        StorageTraceExportJobStatus::Failed => "failed",
        StorageTraceExportJobStatus::Cancelled => "cancelled",
        StorageTraceExportJobStatus::Expired => "expired",
    }
}

fn trace_operational_retention_job_status_name(
    status: StorageTraceRetentionJobStatus,
) -> &'static str {
    match status {
        StorageTraceRetentionJobStatus::Planned => "planned",
        StorageTraceRetentionJobStatus::Running => "running",
        StorageTraceRetentionJobStatus::DryRun => "dry_run",
        StorageTraceRetentionJobStatus::Complete => "complete",
        StorageTraceRetentionJobStatus::Failed => "failed",
        StorageTraceRetentionJobStatus::Paused => "paused",
    }
}

fn trace_operational_credit_event_type_name(
    event_type: TraceCreditLedgerEventType,
) -> &'static str {
    match event_type {
        TraceCreditLedgerEventType::BenchmarkConversion => "benchmark_conversion",
        TraceCreditLedgerEventType::RegressionCatch => "regression_catch",
        TraceCreditLedgerEventType::TrainingUtility => "training_utility",
        TraceCreditLedgerEventType::RankingUtility => "ranking_utility",
        TraceCreditLedgerEventType::ReviewerBonus => "reviewer_bonus",
        TraceCreditLedgerEventType::AbusePenalty => "abuse_penalty",
    }
}

