async fn run_ranker_training_pairs_export_with_grant(
    state: &AppState,
    tenant: &TenantAuth,
    query: RankerTrainingExportQuery,
    grant: TraceExportAccessGrant,
    now: DateTime<Utc>,
) -> ApiResult<Json<TraceRankerTrainingPairExport>> {
    let consent_scope = parse_ranker_consent_scope_filter(query.consent_scope.as_deref())?;
    let purpose =
        normalized_export_purpose(query.purpose.as_deref(), "ranker_training_pairs_export");
    enforce_ranker_export_guardrails(
        state,
        query.purpose.as_deref(),
        query.status,
        query.privacy_risk,
        consent_scope,
    )?;
    let tenant_policy = tenant_export_policy_for_request(
        state,
        tenant,
        "ranker training pairs",
        consent_scope,
        TraceAllowedUse::RankingModelTraining,
    )
    .await?;
    let job = create_validated_export_job_slice(
        state,
        tenant,
        TraceExportDatasetKind::RankerTrainingPairs,
        &purpose,
        query.limit,
        grant.clone(),
        now,
    )?;
    enforce_export_job_mirror_result(
        state,
        "ranker pair export job start",
        mirror_export_job_started_to_db(state, tenant, &grant, &job).await,
    )
    .await
    .map_err(internal_error)?;
    let mut pair_query = query;
    let pair_limit = job.max_item_cap;
    pair_query.limit = Some(pair_limit.saturating_add(1));
    let candidates = fail_export_job_on_error(
        state,
        &job,
        "ranker pair export job failure",
        collect_ranker_training_candidates(
            state,
            tenant,
            &pair_query,
            consent_scope,
            tenant_policy.as_ref(),
        )
        .await,
    )
    .await?;
    let preference_labels = fail_export_job_on_error(
        state,
        &job,
        "ranker pair export job failure",
        read_ranking_preference_labels_for_admin(state, tenant).await,
    )
    .await?;
    let pairs = build_ranker_training_pairs(&candidates, &preference_labels, pair_limit);
    let source_submission_ids = ranker_pair_source_submission_ids(&pairs);
    let source_object_refs = fail_export_job_on_error(
        state,
        &job,
        "ranker pair export job failure",
        revalidate_db_export_sources(
            state,
            tenant,
            &source_submission_ids,
            state.require_derived_export_object_refs_for_tenant(&tenant.tenant_id),
        )
        .await,
    )
    .await?;
    fail_export_job_on_error(
        state,
        &job,
        "ranker pair export job failure",
        append_derived_source_read_audits(
            state,
            tenant,
            &source_submission_ids,
            &source_object_refs,
            "ranker_training_pairs",
            Some(&purpose),
        )
        .await,
    )
    .await?;
    let export_id = Uuid::new_v4();
    let source_item_list_hash = ranker_pair_list_hash(&pairs);
    let audit_event = TraceCommonsAuditEvent::ranker_training_export(
        tenant,
        export_id,
        purpose.as_str(),
        pairs.len(),
        source_item_list_hash.clone(),
    );
    let audit_event_id = audit_event.event_id;
    let provenance = TraceExportProvenanceManifest::new(
        &tenant.tenant_id,
        export_id,
        audit_event_id,
        TraceExportProvenanceKind::RankerTrainingPairs,
        purpose.clone(),
        source_submission_ids,
        source_item_list_hash.clone(),
    );
    let provenance_path = ranker_provenance_path(&state.root, &tenant.tenant_id, export_id);
    let mut required_artifact_object_ref_material = None;
    let object_primary_derived_exports =
        state.object_primary_derived_exports_for_tenant(&tenant.tenant_id);
    if state.require_db_mirror_writes {
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::RankerTrainingExport,
                    export_id,
                    &provenance_path,
                    &provenance,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_ranker_pair_export_provenance_to_db(
            state,
            &provenance,
            &pairs,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                %error,
                export_id = %export_id,
                "Trace Commons DB dual-write ranker pair provenance mirror failed"
            );
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::RankerTrainingExport,
                artifact_object_ref_material.as_ref(),
                std::slice::from_ref(&provenance_path),
            )
            .map_err(internal_error)?;
        }
        enforce_db_mirror_write_result(state, "ranker pair provenance", mirror_result)
            .map_err(internal_error)?;
        required_artifact_object_ref_material = artifact_object_ref_material;
        if !object_primary_derived_exports {
            write_export_provenance(&provenance_path, &provenance).map_err(internal_error)?;
        }
    } else {
        if !object_primary_derived_exports {
            write_export_provenance(&provenance_path, &provenance).map_err(internal_error)?;
        }
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::RankerTrainingExport,
                    export_id,
                    &provenance_path,
                    &provenance,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_ranker_pair_export_provenance_to_db(
            state,
            &provenance,
            &pairs,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                %error,
                export_id = %export_id,
                "Trace Commons DB dual-write ranker pair provenance mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "ranker pair provenance", mirror_result)
            .map_err(internal_error)?;
    }
    let audit_result = append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event.clone(),
        StorageTraceAuditAction::Export,
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: StorageTraceObjectArtifactKind::ExportArtifact,
            purpose_code: Some(purpose.clone()),
            item_count: pairs.len().min(u32::MAX as usize) as u32,
        },
    )
    .await;
    if let Err(error) = audit_result {
        if state.require_db_mirror_writes {
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::RankerTrainingExport,
                required_artifact_object_ref_material.as_ref(),
                std::slice::from_ref(&provenance_path),
            )
            .map_err(internal_error)?;
            rollback_db_export_manifest_publication(state, &tenant.tenant_id, export_id)
                .await
                .map_err(internal_error)?;
            remove_audit_event_by_id(&state.root, &tenant.tenant_id, audit_event.event_id)
                .map_err(internal_error)?;
        }
        return Err(internal_error(error));
    }
    let pair_credit_sources = pairs
        .iter()
        .flat_map(|pair| {
            [
                AutomaticUtilityCreditSource::from_ranker_candidate(&pair.preferred),
                AutomaticUtilityCreditSource::from_ranker_candidate(&pair.rejected),
            ]
        })
        .collect::<Vec<_>>();
    append_automatic_utility_credit_events_once(
        state,
        tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: "ranker-training-pair-credit",
            idempotency_ref: None,
            event_type: TraceCreditLedgerEventType::RankingUtility,
            credit_points_delta: RANKER_TRAINING_PAIR_CREDIT_POINTS_DELTA,
            reason: format!("Exported as ranker training pair {}.", export_id),
            external_ref: format!("ranker_training_pairs_export:{export_id}"),
        },
        pair_credit_sources,
    )
    .await
    .map_err(internal_error)?;
    enforce_export_job_mirror_result(
        state,
        "ranker pair export job completion",
        mirror_export_job_finished_to_db(state, &job, export_id, pairs.len()).await,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceRankerTrainingPairExport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        export_id,
        audit_event_id,
        purpose,
        generated_at: Utc::now(),
        item_count: pairs.len(),
        source_item_list_hash,
        pairs,
    }))
}

#[derive(Debug, Deserialize)]
struct ActiveLearningQueueQuery {
    limit: Option<usize>,
    #[serde(default)]
    privacy_risk: Option<ResidualPiiRisk>,
    #[serde(default)]
    lease_filter: TraceReviewLeaseFilter,
}

async fn active_learning_review_queue_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ActiveLearningQueueQuery>,
) -> ApiResult<Json<TraceActiveLearningReviewQueue>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
    let derived_by_submission = derived
        .into_iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let limit = query.limit.unwrap_or(100).clamp(1, 500);
    let now = Utc::now();
    let mut items = records
        .into_iter()
        .filter(|record| {
            matches!(
                record.status,
                TraceCorpusStatus::Accepted | TraceCorpusStatus::Quarantined
            )
        })
        .filter(|record| !record.is_revoked())
        .filter(|record| {
            query
                .privacy_risk
                .is_none_or(|risk| record.privacy_risk == risk)
        })
        .filter(|record| {
            trace_review_lease_filter_matches(
                record,
                &tenant.principal_ref,
                now,
                query.lease_filter,
            )
        })
        .map(|record| {
            let submission_id = record.submission_id;
            TraceActiveLearningReviewItem::from_record(
                record,
                derived_by_submission.get(&submission_id),
                now,
            )
        })
        .collect::<Vec<_>>();
    items.sort_by(|left, right| {
        right
            .priority_score
            .total_cmp(&left.priority_score)
            .then_with(|| {
                right
                    .review_escalation_state
                    .rank()
                    .cmp(&left.review_escalation_state.rank())
            })
            .then_with(|| right.review_age_hours.cmp(&left.review_age_hours))
            .then_with(|| left.received_at.cmp(&right.received_at))
    });
    items.truncate(limit);
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::read(&tenant, "active_learning_review_queue", items.len()),
        StorageTraceAuditAction::Read,
        StorageTraceAuditSafeMetadata::Empty,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceActiveLearningReviewQueue {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at: Utc::now(),
        item_count: items.len(),
        items,
    }))
}

#[derive(Debug, Deserialize)]
struct TraceMaintenanceRequest {
    #[serde(default)]
    purpose: Option<String>,
    #[serde(default)]
    dry_run: bool,
    #[serde(default)]
    backfill_db_mirror: bool,
    #[serde(default)]
    index_vectors: bool,
    #[serde(default)]
    reconcile_db_mirror: bool,
    #[serde(default)]
    verify_audit_chain: bool,
    #[serde(default = "default_true")]
    prune_export_cache: bool,
    #[serde(default)]
    max_export_age_hours: Option<i64>,
    #[serde(default)]
    purge_expired_before: Option<DateTime<Utc>>,
}

impl TraceMaintenanceRequest {
    fn is_retention_worker_request(&self) -> bool {
        !self.backfill_db_mirror
            && !self.index_vectors
            && !self.reconcile_db_mirror
            && !self.verify_audit_chain
    }

    fn is_vector_worker_request(&self) -> bool {
        self.index_vectors
            && !self.backfill_db_mirror
            && !self.reconcile_db_mirror
            && !self.verify_audit_chain
            && !self.prune_export_cache
            && self.max_export_age_hours.is_none()
            && self.purge_expired_before.is_none()
    }
}

fn default_true() -> bool {
    true
}

async fn maintenance_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceMaintenanceRequest>,
) -> ApiResult<Json<TraceMaintenanceResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_maintenance_operator(&tenant, &body)?;
    require_purge_purpose(
        body.dry_run,
        body.purge_expired_before,
        body.purpose.as_deref(),
    )?;
    let privileged_tenant_policy = if body.purge_expired_before.is_some() {
        tenant_privileged_action_policy_for_request(state.as_ref(), &tenant, "maintenance purge")
            .await?
    } else {
        None
    };
    ensure_maintenance_purge_matches_privileged_action_policy(
        state.as_ref(),
        &tenant,
        body.purge_expired_before,
        privileged_tenant_policy.as_ref(),
    )?;
    let vector_tenant_policy = if body.index_vectors {
        tenant_vector_policy_for_request(state.as_ref(), &tenant).await?
    } else {
        None
    };
    let response = run_maintenance(state.as_ref(), &tenant, body, vector_tenant_policy.as_ref())
        .await
        .map_err(maintenance_error)?;
    Ok(Json(response))
}

#[derive(Debug, Deserialize)]
struct TraceRetentionMaintenanceRequest {
    #[serde(default)]
    purpose: Option<String>,
    #[serde(default)]
    dry_run: bool,
    #[serde(default = "default_true")]
    prune_export_cache: bool,
    #[serde(default)]
    max_export_age_hours: Option<i64>,
    #[serde(default)]
    purge_expired_before: Option<DateTime<Utc>>,
}

async fn retention_maintenance_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRetentionMaintenanceRequest>,
) -> ApiResult<Json<TraceMaintenanceResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_retention_operator(&tenant)?;
    require_purge_purpose(
        body.dry_run,
        body.purge_expired_before,
        body.purpose.as_deref(),
    )?;
    let privileged_tenant_policy = if body.purge_expired_before.is_some() {
        tenant_privileged_action_policy_for_request(state.as_ref(), &tenant, "retention purge")
            .await?
    } else {
        None
    };
    ensure_maintenance_purge_matches_privileged_action_policy(
        state.as_ref(),
        &tenant,
        body.purge_expired_before,
        privileged_tenant_policy.as_ref(),
    )?;
    let response = run_maintenance(
        state.as_ref(),
        &tenant,
        TraceMaintenanceRequest {
            purpose: Some(
                body.purpose
                    .unwrap_or_else(|| "trace_commons_retention_worker".to_string()),
            ),
            dry_run: body.dry_run,
            backfill_db_mirror: false,
            index_vectors: false,
            reconcile_db_mirror: false,
            verify_audit_chain: false,
            prune_export_cache: body.prune_export_cache,
            max_export_age_hours: body.max_export_age_hours,
            purge_expired_before: body.purge_expired_before,
        },
        None,
    )
    .await
    .map_err(maintenance_error)?;
    Ok(Json(response))
}

const TRACE_REVOCATION_PROPAGATION_DEFAULT_LIMIT: u32 = 100;
const TRACE_REVOCATION_PROPAGATION_MAX_LIMIT: u32 = 500;

