fn enforce_tenant_export_policy(
    tenant: &TenantAuth,
    surface: &str,
    policy: Option<&TenantSubmissionPolicy>,
    require_policy: bool,
    requested_scope: Option<ConsentScope>,
    required_use: TraceAllowedUse,
) -> ApiResult<()> {
    let Some(policy) = policy else {
        if require_policy {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                surface,
                "Trace Commons tenant policy rejected export without tenant policy"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace export tenant does not have a contribution policy",
            ));
        }
        return Ok(());
    };

    if let Some(scope) = requested_scope
        && !policy.allowed_consent_scopes.is_empty()
        && !policy.allowed_consent_scopes.contains(&scope)
    {
        tracing::warn!(
            tenant_id = %tenant.tenant_id,
            surface,
            ?scope,
            "Trace Commons tenant policy rejected export consent scope"
        );
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "trace export consent scope is not allowed for this tenant",
        ));
    }

    if !policy.allowed_uses.is_empty() && !policy.allowed_uses.contains(&required_use) {
        tracing::warn!(
            tenant_id = %tenant.tenant_id,
            surface,
            ?required_use,
            "Trace Commons tenant policy rejected export allowed use"
        );
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "trace export use is not allowed for this tenant",
        ));
    }

    Ok(())
}

fn record_matches_export_policy_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    policy: Option<&TenantSubmissionPolicy>,
    required_use: TraceAllowedUse,
) -> bool {
    if !record_matches_scoped_token_export_abac(record, tenant, required_use) {
        return false;
    }

    if !record.allowed_uses.contains(&required_use) {
        return false;
    }

    let Some(policy) = policy else {
        return true;
    };

    if !policy.allowed_consent_scopes.is_empty()
        && !record
            .consent_scopes
            .iter()
            .any(|scope| policy.allowed_consent_scopes.contains(scope))
    {
        return false;
    }

    policy.allowed_uses.is_empty() || policy.allowed_uses.contains(&required_use)
}

fn record_matches_scoped_token_export_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    required_use: TraceAllowedUse,
) -> bool {
    if !tenant.allowed_consent_scopes.is_empty()
        && !record
            .consent_scopes
            .iter()
            .any(|scope| tenant.allowed_consent_scopes.contains(scope))
    {
        return false;
    }

    if !tenant.allowed_uses.is_empty() {
        return tenant.allowed_uses.contains(&required_use)
            && record.allowed_uses.contains(&required_use);
    }

    true
}

fn record_matches_utility_credit_policy_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    policy: Option<&TenantSubmissionPolicy>,
    required_uses: &[TraceAllowedUse],
) -> bool {
    if !record_matches_scoped_token_utility_credit_abac(record, tenant, required_uses) {
        return false;
    }

    if !required_uses
        .iter()
        .any(|required_use| record.allowed_uses.contains(required_use))
    {
        return false;
    }

    let Some(policy) = policy else {
        return true;
    };

    if !policy.allowed_consent_scopes.is_empty()
        && !record
            .consent_scopes
            .iter()
            .any(|scope| policy.allowed_consent_scopes.contains(scope))
    {
        return false;
    }

    policy.allowed_uses.is_empty()
        || required_uses.iter().any(|required_use| {
            policy.allowed_uses.contains(required_use) && record.allowed_uses.contains(required_use)
        })
}

fn record_matches_scoped_token_utility_credit_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    required_uses: &[TraceAllowedUse],
) -> bool {
    if !tenant.allowed_consent_scopes.is_empty()
        && !record
            .consent_scopes
            .iter()
            .any(|scope| tenant.allowed_consent_scopes.contains(scope))
    {
        return false;
    }

    if !tenant.allowed_uses.is_empty() {
        return required_uses.iter().any(|required_use| {
            tenant.allowed_uses.contains(required_use) && record.allowed_uses.contains(required_use)
        });
    }

    true
}

fn record_matches_vector_policy_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    policy: Option<&TenantSubmissionPolicy>,
) -> bool {
    record_matches_utility_credit_policy_abac(record, tenant, policy, VECTOR_INDEX_ALLOWED_USES)
}

fn ensure_record_matches_privileged_action_policy_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    policy: Option<&TenantSubmissionPolicy>,
    surface: &str,
) -> ApiResult<()> {
    if record_matches_privileged_action_policy_abac(record, tenant, policy) {
        return Ok(());
    }
    tracing::warn!(
        tenant_id = %tenant.tenant_id,
        surface,
        submission_id = %record.submission_id,
        "Trace Commons tenant policy rejected privileged action source"
    );
    Err(api_error(
        StatusCode::FORBIDDEN,
        "trace privileged action is not allowed for this tenant source",
    ))
}

fn trace_revocation_reason_for_request(
    auth: &TenantAuth,
    owner_self_revocation: bool,
    reason: Option<&str>,
) -> ApiResult<String> {
    match reason.map(str::trim) {
        Some(reason) if !reason.is_empty() => Ok(reason.to_string()),
        Some(_) => Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace revocation reason cannot be blank",
        )),
        None if auth.role.can_review() && !owner_self_revocation => Err(api_error(
            StatusCode::BAD_REQUEST,
            "privileged trace revocations require a non-empty reason",
        )),
        None => Ok(TRACE_DEFAULT_REVOCATION_REASON.to_string()),
    }
}

fn record_matches_privileged_action_policy_abac(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    policy: Option<&TenantSubmissionPolicy>,
) -> bool {
    if !source_matches_consent_allowlist(&record.consent_scopes, &tenant.allowed_consent_scopes)
        || !source_matches_allowed_use_allowlist(&record.allowed_uses, &tenant.allowed_uses)
    {
        return false;
    }

    let Some(policy) = policy else {
        return true;
    };

    source_matches_consent_allowlist(&record.consent_scopes, &policy.allowed_consent_scopes)
        && source_matches_allowed_use_allowlist(&record.allowed_uses, &policy.allowed_uses)
}

fn source_matches_consent_allowlist(
    source_scopes: &[ConsentScope],
    allowlist: &BTreeSet<ConsentScope>,
) -> bool {
    allowlist.is_empty() || source_scopes.iter().any(|scope| allowlist.contains(scope))
}

fn source_matches_allowed_use_allowlist(
    source_uses: &[TraceAllowedUse],
    allowlist: &BTreeSet<TraceAllowedUse>,
) -> bool {
    allowlist.is_empty()
        || source_uses
            .iter()
            .any(|allowed_use| allowlist.contains(allowed_use))
}

fn ensure_maintenance_purge_matches_privileged_action_policy(
    state: &AppState,
    tenant: &TenantAuth,
    purge_expired_before: Option<DateTime<Utc>>,
    policy: Option<&TenantSubmissionPolicy>,
) -> ApiResult<()> {
    let Some(purge_cutoff) = purge_expired_before else {
        return Ok(());
    };
    let now = Utc::now();
    let records =
        read_all_submission_records(&state.root, &tenant.tenant_id).map_err(internal_error)?;
    for record in records {
        if retention_policy_is_on_legal_hold(state, &record) {
            continue;
        }
        let purge_candidate = record
            .expires_at
            .is_some_and(|expires_at| expires_at <= purge_cutoff)
            && (record.status == TraceCorpusStatus::Expired || record.is_expired_at(now));
        if purge_candidate {
            ensure_record_matches_privileged_action_policy_abac(
                &record,
                tenant,
                policy,
                "maintenance purge",
            )?;
        }
    }
    Ok(())
}

fn authenticate(state: &AppState, headers: &HeaderMap) -> ApiResult<TenantAuth> {
    let authorization = headers
        .get(AUTHORIZATION)
        .ok_or_else(|| api_error(StatusCode::UNAUTHORIZED, "missing bearer token"))?
        .to_str()
        .map_err(|_| api_error(StatusCode::UNAUTHORIZED, "invalid bearer token header"))?;
    let token = authorization
        .strip_prefix("Bearer ")
        .ok_or_else(|| api_error(StatusCode::UNAUTHORIZED, "missing bearer token"))?
        .trim();
    if state.require_eddsa_signed_tokens || state.require_managed_eddsa_signed_tokens {
        if state.tokens.contains_key(token) {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "Trace Commons requires EdDSA signed tenant tokens",
            ));
        }
        let Some(verifier) = &state.signed_token_verifier else {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "Trace Commons requires EdDSA signed tenant tokens",
            ));
        };
        let verifier = verifier.read().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "signed tenant token verifier unavailable",
            )
        })?;
        if state.require_managed_eddsa_signed_tokens
            && state
                .managed_eddsa_keyset_refresh
                .as_ref()
                .and_then(|refresh| refresh.max_stale)
                .is_some_and(|max_stale| verifier.managed_eddsa_keyset_stale(max_stale, Utc::now()))
        {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "stale signed tenant token keyset",
            ));
        }
        return verifier.authenticate(
            token,
            state.require_eddsa_signed_tokens,
            state.require_managed_eddsa_signed_tokens,
        );
    }
    if let Some(auth) = state.tokens.get(token).cloned() {
        if auth
            .expires_at
            .is_some_and(|expires_at| expires_at <= Utc::now())
        {
            return Err(api_error(StatusCode::FORBIDDEN, "expired tenant token"));
        }
        return Ok(auth);
    }
    if let Some(verifier) = &state.signed_token_verifier {
        let verifier = verifier.read().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "signed tenant token verifier unavailable",
            )
        })?;
        return verifier.authenticate(token, false, false);
    }
    Err(api_error(StatusCode::FORBIDDEN, "unknown tenant token"))
}

fn authenticate_ctx(state: &AppState, headers: &HeaderMap) -> ApiResult<TenantCtx> {
    authenticate(state, headers).map(TenantCtx::from_auth)
}

async fn authenticate_with_tenant_access_grant(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<TenantAuth> {
    authorize_tenant_access_grant(state, authenticate(state, headers)?).await
}

async fn authenticate_ctx_with_tenant_access_grant(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<TenantCtx> {
    authorize_tenant_access_grant_ctx(state, authenticate_ctx(state, headers)?).await
}

