fn push_gap_count(gaps: &mut Vec<String>, name: &str, count: usize) {
    if count > 0 {
        gaps.push(format!("{name}={count}"));
    }
}

fn push_gap_bool(gaps: &mut Vec<String>, name: &str, ok: bool) {
    if !ok {
        gaps.push(format!("{name}=failed"));
    }
}

