#[derive(Debug, Serialize)]
struct TraceCommonsTenantCreditResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    accepted: usize,
    quarantined: usize,
    revoked: usize,
    rejected: usize,
    expired: usize,
    credit_points_pending: f32,
    credit_points_final: f32,
    credit_points_ledger: f32,
    credit_points_total: f32,
    credit_points_estimated: f32,
    credit_points_pending_ledger: f32,
    credit_points_settled: f32,
    credit_points_reversed: f32,
    credit_points_held: f32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_settlement_batch_id: Option<Uuid>,
}

impl TraceCommonsTenantCreditResponse {
    fn from_records_events_and_settlements(
        tenant_id: String,
        auth: &TenantAuth,
        records: Vec<TraceCommonsSubmissionRecord>,
        credit_events: &[TraceCommonsCreditLedgerRecord],
        settlement_batches: &[TraceCreditSettlementBatchRecord],
        credit_holds: &[TraceCreditHoldRecord],
    ) -> Self {
        let mut response = Self {
            tenant_storage_ref: tenant_storage_ref(&tenant_id),
            tenant_id,
            accepted: 0,
            quarantined: 0,
            revoked: 0,
            rejected: 0,
            expired: 0,
            credit_points_pending: 0.0,
            credit_points_final: 0.0,
            credit_points_ledger: 0.0,
            credit_points_total: 0.0,
            credit_points_estimated: 0.0,
            credit_points_pending_ledger: 0.0,
            credit_points_settled: 0.0,
            credit_points_reversed: 0.0,
            credit_points_held: 0.0,
            last_settlement_batch_id: None,
        };

        let delayed_credit_eligible_submission_ids = records
            .iter()
            .filter(|record| delayed_credit_applies_to_record(record))
            .map(|record| record.submission_id)
            .collect::<BTreeSet<_>>();

        for record in &records {
            match record.status {
                TraceCorpusStatus::Accepted => {
                    response.accepted += 1;
                    response.credit_points_pending += record.credit_points_pending;
                    response.credit_points_estimated += record.credit_points_pending;
                    response.credit_points_final += record.credit_points_final.unwrap_or(0.0);
                }
                TraceCorpusStatus::Quarantined => response.quarantined += 1,
                TraceCorpusStatus::Revoked => response.revoked += 1,
                TraceCorpusStatus::Rejected => response.rejected += 1,
                TraceCorpusStatus::Expired | TraceCorpusStatus::Purged => response.expired += 1,
            }
        }

        let principal_ref = auth.principal_ref.as_str();
        let tenant_wide_credit_view = auth.role.can_review();
        let legacy_principal_ref = legacy_principal_ref();
        let legacy_principal_ref = legacy_principal_ref.as_str();
        let visible_settlements = settlement_batches
            .iter()
            .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
            .flat_map(|batch| {
                batch.line_items.iter().filter_map(move |item| {
                    (tenant_wide_credit_view
                        || item.credit_account_ref == principal_ref
                        || item.credit_account_ref == legacy_principal_ref)
                        .then_some((batch.settlement_batch_id, item))
                })
            })
            .collect::<Vec<_>>();
        let settled_credit_event_ids = visible_settlements
            .iter()
            .flat_map(|(_, item)| item.source_credit_event_ids.iter().copied())
            .collect::<BTreeSet<_>>();
        response.credit_points_settled = visible_settlements
            .iter()
            .map(|(_, item)| item.settled_credit_delta_micros as f32 / 1_000_000.0)
            .sum();
        response.last_settlement_batch_id = visible_settlements
            .iter()
            .map(|(batch_id, _)| *batch_id)
            .next_back();
        let held_account_refs = credit_holds
            .iter()
            .filter(|hold| hold.released_at.is_none())
            .filter(|hold| {
                tenant_wide_credit_view
                    || hold.credit_account_ref == principal_ref
                    || hold.credit_account_ref == legacy_principal_ref
            })
            .map(|hold| hold.credit_account_ref.as_str())
            .collect::<BTreeSet<_>>();
        response.credit_points_held = credit_events
            .iter()
            .filter(|event| delayed_credit_eligible_submission_ids.contains(&event.submission_id))
            .filter(|event| !settled_credit_event_ids.contains(&event.event_id))
            .filter(|event| held_account_refs.contains(event.auth_principal_ref.as_str()))
            .map(|event| event.credit_points_delta)
            .sum();
        response.credit_points_pending_ledger = credit_events
            .iter()
            .filter(|event| delayed_credit_eligible_submission_ids.contains(&event.submission_id))
            .filter(|event| !settled_credit_event_ids.contains(&event.event_id))
            .filter(|event| !held_account_refs.contains(event.auth_principal_ref.as_str()))
            .map(|event| event.credit_points_delta)
            .sum();
        response.credit_points_ledger =
            response.credit_points_pending_ledger + response.credit_points_settled;
        response.credit_points_total = response.credit_points_final + response.credit_points_ledger;
        response
    }
}

#[derive(Debug, Serialize)]
struct TraceCommonsAnalyticsResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    submissions_total: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    min_cell_count: Option<usize>,
    #[serde(default, skip_serializing_if = "is_zero")]
    suppressed_cell_count: usize,
    by_status: BTreeMap<String, usize>,
    by_privacy_risk: BTreeMap<String, usize>,
    by_task_success: BTreeMap<String, usize>,
    by_tool: BTreeMap<String, usize>,
    by_tool_category: BTreeMap<String, usize>,
    coverage_tags: BTreeMap<String, usize>,
    process_evaluation: TraceProcessEvaluationAnalytics,
    duplicate_groups: usize,
    average_novelty_score: f32,
}

#[derive(Debug, Default, Clone, Serialize, PartialEq, Eq)]
struct TraceProcessEvaluationAnalytics {
    evaluated_traces: usize,
    by_label: BTreeMap<String, usize>,
    by_rating: BTreeMap<String, BTreeMap<String, usize>>,
    by_score_band: BTreeMap<String, usize>,
}

impl TraceProcessEvaluationAnalytics {
    fn record_coverage_tags(&mut self, coverage_tags: &[String]) {
        let mut has_process_evaluation = false;
        for tag in coverage_tags {
            if let Some(label) = tag.strip_prefix("process_label:") {
                has_process_evaluation = true;
                *self.by_label.entry(label.to_string()).or_insert(0) += 1;
                continue;
            }
            if let Some(score_band) = tag.strip_prefix("process_eval:") {
                has_process_evaluation = true;
                *self
                    .by_score_band
                    .entry(score_band.to_string())
                    .or_insert(0) += 1;
                continue;
            }
            if let Some((axis, rating)) = tag
                .strip_prefix("process_")
                .and_then(|value| value.split_once(':'))
            {
                has_process_evaluation = true;
                *self
                    .by_rating
                    .entry(axis.to_string())
                    .or_default()
                    .entry(rating.to_string())
                    .or_insert(0) += 1;
            }
        }
        if has_process_evaluation {
            self.evaluated_traces += 1;
        }
    }

    fn apply_min_cell_count(&mut self, min_cell_count: usize) -> usize {
        let mut suppressed = 0usize;
        suppressed += suppress_small_analytics_cells(&mut self.by_label, min_cell_count);
        suppressed += suppress_small_analytics_cells(&mut self.by_score_band, min_cell_count);
        let axes = self.by_rating.keys().cloned().collect::<Vec<_>>();
        for axis in axes {
            if let Some(cells) = self.by_rating.get_mut(&axis) {
                suppressed += suppress_small_analytics_cells(cells, min_cell_count);
            }
            if self.by_rating.get(&axis).is_some_and(BTreeMap::is_empty) {
                self.by_rating.remove(&axis);
            }
        }
        suppressed
    }
}

impl TraceCommonsAnalyticsResponse {
    fn from_records(
        tenant_id: String,
        records: Vec<TraceCommonsSubmissionRecord>,
        derived: Vec<TraceCommonsDerivedRecord>,
    ) -> Self {
        let mut response = Self {
            tenant_storage_ref: tenant_storage_ref(&tenant_id),
            tenant_id,
            submissions_total: records.len(),
            min_cell_count: None,
            suppressed_cell_count: 0,
            by_status: BTreeMap::new(),
            by_privacy_risk: BTreeMap::new(),
            by_task_success: BTreeMap::new(),
            by_tool: BTreeMap::new(),
            by_tool_category: BTreeMap::new(),
            coverage_tags: BTreeMap::new(),
            process_evaluation: TraceProcessEvaluationAnalytics::default(),
            duplicate_groups: 0,
            average_novelty_score: 0.0,
        };

        for record in &records {
            *response
                .by_status
                .entry(record.status.as_str().to_string())
                .or_insert(0) += 1;
            *response
                .by_privacy_risk
                .entry(format!("{:?}", record.privacy_risk).to_ascii_lowercase())
                .or_insert(0) += 1;
        }

        let mut summary_hash_counts = BTreeMap::<String, usize>::new();
        let mut novelty_total = 0.0f32;
        for record in &derived {
            *response
                .by_task_success
                .entry(record.task_success.to_ascii_lowercase())
                .or_insert(0) += 1;
            for tool in &record.tool_sequence {
                *response.by_tool.entry(tool.clone()).or_insert(0) += 1;
            }
            for category in &record.tool_categories {
                *response
                    .by_tool_category
                    .entry(category.clone())
                    .or_insert(0) += 1;
            }
            for tag in &record.coverage_tags {
                *response.coverage_tags.entry(tag.clone()).or_insert(0) += 1;
            }
            response
                .process_evaluation
                .record_coverage_tags(&record.coverage_tags);
            *summary_hash_counts
                .entry(record.canonical_summary_hash.clone())
                .or_insert(0) += 1;
            novelty_total += record.novelty_score;
        }

        response.duplicate_groups = summary_hash_counts
            .values()
            .filter(|count| **count > 1)
            .count();
        if !derived.is_empty() {
            response.average_novelty_score = novelty_total / derived.len() as f32;
        }
        response
    }

    fn apply_min_cell_count(&mut self, min_cell_count: usize) {
        if min_cell_count <= 1 {
            return;
        }
        self.min_cell_count = Some(min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_status, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_privacy_risk, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_task_success, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_tool, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.by_tool_category, min_cell_count);
        self.suppressed_cell_count +=
            suppress_small_analytics_cells(&mut self.coverage_tags, min_cell_count);
        self.suppressed_cell_count += self.process_evaluation.apply_min_cell_count(min_cell_count);
    }
}

#[derive(Debug, Serialize)]
struct TraceOperationalSummaryResponse {
    tenant_id: String,
    tenant_storage_ref: String,
    generated_at: DateTime<Utc>,
    promotion_gates: TraceOperationalPromotionGateSummary,
    submissions: TraceOperationalSubmissionSummary,
    review_sla: TraceOperationalReviewSlaSummary,
    exports: TraceOperationalExportSummary,
    retention: TraceOperationalRetentionSummary,
    vectors: TraceOperationalVectorSummary,
    benchmarks: TraceOperationalBenchmarkSummary,
    ranking: TraceOperationalRankingSummary,
    delayed_credit: TraceOperationalDelayedCreditSummary,
}

struct TraceOperationalSummaryInputs<'a> {
    state: &'a AppState,
    tenant_id: String,
    records: Vec<TraceCommonsSubmissionRecord>,
    derived: Vec<TraceCommonsDerivedRecord>,
    credit_events: Vec<TraceCommonsCreditLedgerRecord>,
    db_summary: TraceOperationalDbSummary,
    benchmark_artifacts: Vec<TraceBenchmarkConversionArtifact>,
    benchmark_registry_outbox: Vec<TraceBenchmarkRegistryOutboxItem>,
    ranking: TraceOperationalRankingSummary,
    generated_at: DateTime<Utc>,
}

impl TraceOperationalSummaryResponse {
    fn from_parts(inputs: TraceOperationalSummaryInputs<'_>) -> Self {
        let submissions = TraceOperationalSubmissionSummary::from_records(&inputs.records);
        let review_sla =
            TraceOperationalReviewSlaSummary::from_records(&inputs.records, inputs.generated_at);
        let delayed_credit =
            TraceOperationalDelayedCreditSummary::from_events(&inputs.credit_events);
        let exports = TraceOperationalExportSummary::from_db_summary(&inputs.db_summary);
        let retention = TraceOperationalRetentionSummary::from_db_summary(&inputs.db_summary);
        let vectors = TraceOperationalVectorSummary::from_records_and_db_summary(
            &inputs.derived,
            &inputs.db_summary,
        );
        let benchmarks = TraceOperationalBenchmarkSummary::from_artifacts_and_registry_outbox(
            &inputs.benchmark_artifacts,
            &inputs.benchmark_registry_outbox,
        );
        let promotion_gates = TraceOperationalPromotionGateSummary::from_state_and_summaries(
            inputs.state,
            &review_sla,
            &exports,
            &retention,
            &vectors,
            &benchmarks,
            &inputs.ranking,
        );
        Self {
            tenant_storage_ref: tenant_storage_ref(&inputs.tenant_id),
            tenant_id: inputs.tenant_id,
            generated_at: inputs.generated_at,
            promotion_gates,
            submissions,
            review_sla,
            exports,
            retention,
            vectors,
            benchmarks,
            ranking: inputs.ranking,
            delayed_credit,
        }
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalPromotionGateSummary {
    ready: bool,
    blocking_count: usize,
    warning_count: usize,
    blocking_gates: Vec<String>,
    warning_gates: Vec<String>,
    db_mirror_configured: bool,
    require_db_mirror_writes: bool,
    require_db_reconciliation_clean: bool,
    require_derived_export_object_refs: bool,
    require_export_guardrails: bool,
    object_primary_submit_review: bool,
    object_primary_replay_export: bool,
    object_primary_derived_exports: bool,
    tenant_rollout_gate_count: usize,
    tenant_rollout_gate_counts: BTreeMap<String, usize>,
    open_review_count: usize,
    urgent_review_count: usize,
    failed_export_job_count: usize,
    failed_retention_job_count: usize,
    vector_missing_count: usize,
    published_benchmark_external_registry_gap_count: usize,
    revoked_benchmark_external_registry_invalidation_gap_count: usize,
    at_risk_ranking_model_count: usize,
    failing_ranking_model_backtest_count: usize,
    ranking_adjudication_issue_count: usize,
    blocked_ranking_credit_event_count: usize,
    ranking_calibration_dataset_manifest_conflict_count: usize,
    stale_ranking_worker_run_count: usize,
}

impl TraceOperationalPromotionGateSummary {
    fn from_state_and_summaries(
        state: &AppState,
        review_sla: &TraceOperationalReviewSlaSummary,
        exports: &TraceOperationalExportSummary,
        retention: &TraceOperationalRetentionSummary,
        vectors: &TraceOperationalVectorSummary,
        benchmarks: &TraceOperationalBenchmarkSummary,
        ranking: &TraceOperationalRankingSummary,
    ) -> Self {
        let db_mirror_configured = state.db_mirror.is_some();
        let tenant_rollout_gate_counts = state.tenant_rollout_gates.status_counts();
        let tenant_rollout_gate_count = tenant_rollout_gate_counts.values().sum();
        let open_review_count = review_sla.quarantined_total;
        let urgent_review_count = review_sla.urgent;
        let failed_export_job_count = exports.jobs_by_status.get("failed").copied().unwrap_or(0);
        let failed_retention_job_count =
            retention.jobs_by_status.get("failed").copied().unwrap_or(0);
        let vector_missing_count = vectors
            .accepted_current_derived
            .saturating_sub(vectors.accepted_current_derived_with_active_vector);
        let published_benchmark_external_registry_gap_count =
            benchmarks.external_registry_adapter_gap_count;
        let revoked_benchmark_external_registry_invalidation_gap_count =
            benchmarks.external_registry_invalidation_gap_count;
        let at_risk_ranking_model_count = ranking.at_risk_model_count;
        let failing_ranking_model_backtest_count = ranking.failing_backtest_model_target_count;
        let ranking_adjudication_issue_count = ranking.adjudication_issue_group_count;
        let blocked_ranking_credit_event_count = ranking.blocked_credit_event_count;
        let ranking_calibration_dataset_manifest_conflict_count =
            ranking.calibration_dataset_manifest_conflict_count;
        let stale_ranking_worker_run_count = ranking.stale_running_worker_run_count;
        let mut blocking_gates = Vec::new();
        let mut warning_gates = Vec::new();

        push_gap_count(&mut blocking_gates, "urgent_reviews", urgent_review_count);
        push_gap_count(
            &mut blocking_gates,
            "failed_export_jobs",
            failed_export_job_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "failed_retention_jobs",
            failed_retention_job_count,
        );
        if state.require_db_mirror_writes && !db_mirror_configured {
            blocking_gates.push("db_mirror_writes_required_without_db_mirror".to_string());
        }
        if state.require_db_reconciliation_clean && !db_mirror_configured {
            blocking_gates.push("db_reconciliation_clean_required_without_db_mirror".to_string());
        }
        if state.require_derived_export_object_refs && !db_mirror_configured {
            blocking_gates
                .push("derived_export_object_refs_required_without_db_mirror".to_string());
        }
        if (state.object_primary_submit_review
            || state.object_primary_replay_export
            || state.object_primary_derived_exports)
            && !db_mirror_configured
        {
            blocking_gates.push("object_primary_storage_required_without_db_mirror".to_string());
        }
        if state.require_derived_export_object_refs {
            push_gap_count(
                &mut blocking_gates,
                "missing_active_vectors",
                vector_missing_count,
            );
        }
        push_gap_count(
            &mut blocking_gates,
            "at_risk_ranking_models",
            at_risk_ranking_model_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "failing_ranking_model_backtests",
            failing_ranking_model_backtest_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "ranking_adjudication_issues",
            ranking_adjudication_issue_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "blocked_ranking_credit_events",
            blocked_ranking_credit_event_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "ranking_calibration_dataset_manifest_conflicts",
            ranking_calibration_dataset_manifest_conflict_count,
        );
        push_gap_count(
            &mut blocking_gates,
            "stale_ranking_worker_runs",
            stale_ranking_worker_run_count,
        );

        push_gap_count(
            &mut warning_gates,
            "non_urgent_open_reviews",
            open_review_count.saturating_sub(urgent_review_count),
        );
        push_gap_count(
            &mut warning_gates,
            "tenant_rollout_gates",
            tenant_rollout_gate_count,
        );
        push_gap_count(
            &mut warning_gates,
            "published_benchmarks_waiting_for_external_registry_adapter",
            published_benchmark_external_registry_gap_count,
        );
        push_gap_count(
            &mut warning_gates,
            "revoked_benchmarks_waiting_for_external_registry_invalidation",
            revoked_benchmark_external_registry_invalidation_gap_count,
        );

        Self {
            ready: blocking_gates.is_empty(),
            blocking_count: blocking_gates.len(),
            warning_count: warning_gates.len(),
            blocking_gates,
            warning_gates,
            db_mirror_configured,
            require_db_mirror_writes: state.require_db_mirror_writes,
            require_db_reconciliation_clean: state.require_db_reconciliation_clean,
            require_derived_export_object_refs: state.require_derived_export_object_refs,
            require_export_guardrails: state.require_export_guardrails,
            object_primary_submit_review: state.object_primary_submit_review,
            object_primary_replay_export: state.object_primary_replay_export,
            object_primary_derived_exports: state.object_primary_derived_exports,
            tenant_rollout_gate_count,
            tenant_rollout_gate_counts,
            open_review_count,
            urgent_review_count,
            failed_export_job_count,
            failed_retention_job_count,
            vector_missing_count,
            published_benchmark_external_registry_gap_count,
            revoked_benchmark_external_registry_invalidation_gap_count,
            at_risk_ranking_model_count,
            failing_ranking_model_backtest_count,
            ranking_adjudication_issue_count,
            blocked_ranking_credit_event_count,
            ranking_calibration_dataset_manifest_conflict_count,
            stale_ranking_worker_run_count,
        }
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalSubmissionSummary {
    total: usize,
    by_status: BTreeMap<String, usize>,
    by_privacy_risk: BTreeMap<String, usize>,
    accepted: usize,
    quarantined: usize,
    rejected: usize,
    revoked: usize,
    expired: usize,
    purged: usize,
}

impl TraceOperationalSubmissionSummary {
    fn from_records(records: &[TraceCommonsSubmissionRecord]) -> Self {
        let mut summary = Self {
            total: records.len(),
            ..Self::default()
        };
        for record in records {
            *summary
                .by_status
                .entry(record.status.as_str().to_string())
                .or_insert(0) += 1;
            *summary
                .by_privacy_risk
                .entry(format!("{:?}", record.privacy_risk).to_ascii_lowercase())
                .or_insert(0) += 1;
            match record.status {
                TraceCorpusStatus::Accepted => summary.accepted += 1,
                TraceCorpusStatus::Quarantined => summary.quarantined += 1,
                TraceCorpusStatus::Rejected => summary.rejected += 1,
                TraceCorpusStatus::Revoked => summary.revoked += 1,
                TraceCorpusStatus::Expired => summary.expired += 1,
                TraceCorpusStatus::Purged => summary.purged += 1,
            }
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalReviewSlaSummary {
    quarantined_total: usize,
    fresh: usize,
    due: usize,
    overdue: usize,
    urgent: usize,
    assigned: usize,
    expired_leases: usize,
    oldest_age_hours: i64,
    by_state: BTreeMap<String, usize>,
}

impl TraceOperationalReviewSlaSummary {
    fn from_records(records: &[TraceCommonsSubmissionRecord], now: DateTime<Utc>) -> Self {
        let mut summary = Self::default();
        for record in records
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        {
            summary.quarantined_total += 1;
            if record.review_assigned_to_principal_ref.is_some() {
                summary.assigned += 1;
            }
            if record
                .review_lease_expires_at
                .is_some_and(|expires_at| expires_at <= now)
            {
                summary.expired_leases += 1;
            }
            let escalation = trace_review_escalation(record, now);
            summary.oldest_age_hours = summary.oldest_age_hours.max(escalation.age_hours);
            let state_name = trace_operational_review_state_name(escalation.state);
            *summary.by_state.entry(state_name.to_string()).or_insert(0) += 1;
            match escalation.state {
                TraceReviewEscalationState::Fresh => summary.fresh += 1,
                TraceReviewEscalationState::Due => summary.due += 1,
                TraceReviewEscalationState::Overdue => summary.overdue += 1,
                TraceReviewEscalationState::Urgent => summary.urgent += 1,
            }
        }
        summary
    }
}

fn trace_operational_review_state_name(state: TraceReviewEscalationState) -> &'static str {
    match state {
        TraceReviewEscalationState::Fresh => "fresh",
        TraceReviewEscalationState::Due => "due",
        TraceReviewEscalationState::Overdue => "overdue",
        TraceReviewEscalationState::Urgent => "urgent",
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalExportSummary {
    db_available: bool,
    manifest_count: usize,
    active_manifest_count: usize,
    invalidated_manifest_count: usize,
    deleted_manifest_count: usize,
    total_manifest_items: usize,
    by_artifact_kind: BTreeMap<String, usize>,
    job_count: usize,
    jobs_by_status: BTreeMap<String, usize>,
}

impl TraceOperationalExportSummary {
    fn from_db_summary(db_summary: &TraceOperationalDbSummary) -> Self {
        let mut summary = Self {
            db_available: db_summary.db_available,
            manifest_count: db_summary.export_manifests.len(),
            job_count: db_summary.export_jobs.len(),
            ..Self::default()
        };
        for manifest in &db_summary.export_manifests {
            if manifest.deleted_at.is_some() {
                summary.deleted_manifest_count += 1;
            } else if manifest.invalidated_at.is_some() {
                summary.invalidated_manifest_count += 1;
            } else {
                summary.active_manifest_count += 1;
            }
            summary.total_manifest_items += manifest.item_count as usize;
            *summary
                .by_artifact_kind
                .entry(trace_operational_artifact_kind_name(manifest.artifact_kind).to_string())
                .or_insert(0) += 1;
        }
        for job in &db_summary.export_jobs {
            *summary
                .jobs_by_status
                .entry(trace_operational_export_job_status_name(job.status).to_string())
                .or_insert(0) += 1;
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalRetentionSummary {
    db_available: bool,
    job_count: usize,
    dry_run_count: usize,
    jobs_by_status: BTreeMap<String, usize>,
    selected_revoked_total: u64,
    selected_expired_total: u64,
}

impl TraceOperationalRetentionSummary {
    fn from_db_summary(db_summary: &TraceOperationalDbSummary) -> Self {
        let mut summary = Self {
            db_available: db_summary.db_available,
            job_count: db_summary.retention_jobs.len(),
            ..Self::default()
        };
        for job in &db_summary.retention_jobs {
            if job.dry_run {
                summary.dry_run_count += 1;
            }
            summary.selected_revoked_total += u64::from(job.selected_revoked_count);
            summary.selected_expired_total += u64::from(job.selected_expired_count);
            *summary
                .jobs_by_status
                .entry(trace_operational_retention_job_status_name(job.status).to_string())
                .or_insert(0) += 1;
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalVectorSummary {
    db_available: bool,
    entry_count: usize,
    active_entries: usize,
    invalidated_entries: usize,
    deleted_entries: usize,
    accepted_current_derived: usize,
    accepted_current_derived_with_active_vector: usize,
    active_coverage_percent: f32,
}

impl TraceOperationalVectorSummary {
    fn from_records_and_db_summary(
        derived: &[TraceCommonsDerivedRecord],
        db_summary: &TraceOperationalDbSummary,
    ) -> Self {
        let active_vector_submission_ids = db_summary
            .vector_entries
            .iter()
            .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
            .map(|entry| entry.submission_id)
            .collect::<BTreeSet<_>>();
        let accepted_current_derived = derived
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Accepted)
            .count();
        let accepted_current_derived_with_active_vector = derived
            .iter()
            .filter(|record| record.status == TraceCorpusStatus::Accepted)
            .filter(|record| active_vector_submission_ids.contains(&record.submission_id))
            .count();
        let mut summary = Self {
            db_available: db_summary.db_available,
            entry_count: db_summary.vector_entries.len(),
            accepted_current_derived,
            accepted_current_derived_with_active_vector,
            active_coverage_percent: if accepted_current_derived == 0 {
                0.0
            } else {
                (accepted_current_derived_with_active_vector as f32
                    / accepted_current_derived as f32)
                    * 100.0
            },
            ..Self::default()
        };
        for entry in &db_summary.vector_entries {
            match entry.status {
                StorageTraceVectorEntryStatus::Active => summary.active_entries += 1,
                StorageTraceVectorEntryStatus::Invalidated => summary.invalidated_entries += 1,
                StorageTraceVectorEntryStatus::Deleted => summary.deleted_entries += 1,
            }
        }
        summary
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalBenchmarkSummary {
    total_artifact_count: usize,
    by_registry_status: BTreeMap<String, usize>,
    by_evaluation_status: BTreeMap<String, usize>,
    candidate_not_evaluated_count: usize,
    evaluated_passed_unpublished_count: usize,
    evaluated_failed_count: usize,
    evaluated_inconclusive_count: usize,
    incomplete_evaluator_metadata_count: usize,
    publishable_count: usize,
    published_count: usize,
    revoked_count: usize,
    registry_outbox_pending_count: usize,
    registry_outbox_submitted_count: usize,
    registry_outbox_confirmed_count: usize,
    registry_outbox_failed_count: usize,
    external_registry_adapter_gap_count: usize,
    external_registry_invalidation_gap_count: usize,
    blocker_reasons: Vec<String>,
}

impl TraceOperationalBenchmarkSummary {
    fn from_artifacts_and_registry_outbox(
        artifacts: &[TraceBenchmarkConversionArtifact],
        registry_outbox: &[TraceBenchmarkRegistryOutboxItem],
    ) -> Self {
        let mut summary = Self {
            total_artifact_count: artifacts.len(),
            ..Self::default()
        };
        let mut confirmed_publish_conversion_ids = BTreeSet::new();
        let mut confirmed_revoke_conversion_ids = BTreeSet::new();
        for item in registry_outbox {
            if item.operation == StorageTraceBenchmarkRegistryOutboxOperation::Publish
                && item.status == StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
            {
                confirmed_publish_conversion_ids.insert(item.conversion_id);
            }
            if item.operation == StorageTraceBenchmarkRegistryOutboxOperation::Revoke
                && item.status == StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
            {
                confirmed_revoke_conversion_ids.insert(item.conversion_id);
            }
            match item.status {
                StorageTraceBenchmarkRegistryOutboxStatus::Pending => {
                    summary.registry_outbox_pending_count += 1;
                }
                StorageTraceBenchmarkRegistryOutboxStatus::Submitted => {
                    summary.registry_outbox_submitted_count += 1;
                }
                StorageTraceBenchmarkRegistryOutboxStatus::Confirmed => {
                    summary.registry_outbox_confirmed_count += 1;
                }
                StorageTraceBenchmarkRegistryOutboxStatus::Failed => {
                    summary.registry_outbox_failed_count += 1;
                }
            }
        }
        for artifact in artifacts {
            *summary
                .by_registry_status
                .entry(artifact.registry.status.as_str().to_string())
                .or_insert(0) += 1;
            *summary
                .by_evaluation_status
                .entry(artifact.evaluation.status.as_str().to_string())
                .or_insert(0) += 1;

            match artifact.registry.status {
                TraceBenchmarkRegistryStatus::Candidate => match artifact.evaluation.status {
                    TraceBenchmarkEvaluationStatus::NotRun => {
                        summary.candidate_not_evaluated_count += 1;
                    }
                    TraceBenchmarkEvaluationStatus::Passed => {
                        summary.evaluated_passed_unpublished_count += 1;
                        if !benchmark_artifact_has_publishable_evaluation_metadata(artifact) {
                            summary.incomplete_evaluator_metadata_count += 1;
                        }
                    }
                    TraceBenchmarkEvaluationStatus::Failed => {
                        summary.evaluated_failed_count += 1;
                    }
                    TraceBenchmarkEvaluationStatus::Inconclusive => {
                        summary.evaluated_inconclusive_count += 1;
                    }
                    TraceBenchmarkEvaluationStatus::Queued
                    | TraceBenchmarkEvaluationStatus::Running => {}
                },
                TraceBenchmarkRegistryStatus::Published => {
                    summary.published_count += 1;
                    if !confirmed_publish_conversion_ids.contains(&artifact.conversion_id) {
                        summary.external_registry_adapter_gap_count += 1;
                    }
                }
                TraceBenchmarkRegistryStatus::Revoked => {
                    summary.revoked_count += 1;
                    if artifact.registry.registry_ref.is_some()
                        && !confirmed_revoke_conversion_ids.contains(&artifact.conversion_id)
                    {
                        summary.external_registry_invalidation_gap_count += 1;
                    }
                }
            }
            if benchmark_artifact_is_publishable_by_worker(artifact) {
                summary.publishable_count += 1;
            }
        }
        push_gap_count(
            &mut summary.blocker_reasons,
            "benchmark_evaluation_pending",
            summary.candidate_not_evaluated_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "benchmark_registry_publication_pending",
            summary.publishable_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "benchmark_evaluator_metadata_incomplete",
            summary.incomplete_evaluator_metadata_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "benchmark_evaluation_failed",
            summary.evaluated_failed_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "external_benchmark_registry_adapter_gap",
            summary.external_registry_adapter_gap_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "external_benchmark_registry_invalidation_gap",
            summary.external_registry_invalidation_gap_count,
        );
        push_gap_count(
            &mut summary.blocker_reasons,
            "benchmark_registry_outbox_failed",
            summary.registry_outbox_failed_count,
        );
        summary
    }
}

struct TraceOperationalRankingInputs<'a> {
    state: &'a AppState,
    tenant: &'a TenantAuth,
    credit_events: &'a [TraceCommonsCreditLedgerRecord],
    settlement_batches: &'a [TraceCreditSettlementBatchRecord],
    held_credit_accounts: &'a BTreeSet<String>,
    model_versions: &'a [TraceRankingModelVersionRecord],
    features: &'a [TraceRankingFeatureRecord],
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
    calibration_dataset_manifest_conflict_count: usize,
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
    worker_runs: &'a [TraceRankingWorkerRunRecord],
    generated_at: DateTime<Utc>,
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalRankingSummary {
    active_model_count: usize,
    monitored_model_count: usize,
    at_risk_model_count: usize,
    risk_code_counts: BTreeMap<String, usize>,
    backtest_model_target_count: usize,
    passing_backtest_model_target_count: usize,
    failing_backtest_model_target_count: usize,
    backtest_reason_counts: BTreeMap<String, usize>,
    adjudication_issue_group_count: usize,
    unresolved_disputed_label_group_count: usize,
    conflicting_absolute_label_group_count: usize,
    conflicting_preference_pair_count: usize,
    adjudication_reason_counts: BTreeMap<String, usize>,
    pending_credit_event_count: usize,
    ready_credit_event_count: usize,
    blocked_credit_event_count: usize,
    blocked_credit_reason_counts: BTreeMap<String, usize>,
    calibration_dataset_manifest_conflict_count: usize,
    running_worker_run_count: usize,
    stale_running_worker_run_count: usize,
    failed_worker_run_count: usize,
}

impl TraceOperationalRankingSummary {
    fn from_inputs(inputs: TraceOperationalRankingInputs<'_>) -> Self {
        let risk = ranking_model_risk_report(
            inputs.state,
            inputs.tenant,
            inputs.model_versions,
            RankingModelRiskEvidence {
                predictions: inputs.predictions,
                labels: inputs.labels,
                preference_labels: inputs.preference_labels,
                calibration_datasets: inputs.calibration_datasets,
                calibration_runs: inputs.calibration_runs,
            },
        );
        let backtest = ranking_model_backtest_report(
            inputs.state,
            inputs.tenant,
            inputs.model_versions,
            RankingModelRiskEvidence {
                predictions: inputs.predictions,
                labels: inputs.labels,
                preference_labels: inputs.preference_labels,
                calibration_datasets: inputs.calibration_datasets,
                calibration_runs: inputs.calibration_runs,
            },
        );
        let adjudication = ranking_adjudication_report(
            &inputs.tenant.tenant_id,
            inputs.labels,
            inputs.preference_labels,
        );
        let readiness = ranking_credit_readiness_report(RankingCreditReadinessInputs {
            state: inputs.state,
            tenant: inputs.tenant,
            credit_events: inputs.credit_events,
            settlement_batches: inputs.settlement_batches,
            held_credit_accounts: inputs.held_credit_accounts,
            features: inputs.features,
            predictions: inputs.predictions,
            model_versions: inputs.model_versions,
            labels: inputs.labels,
            preference_labels: inputs.preference_labels,
            calibration_datasets: inputs.calibration_datasets,
            calibration_dataset_manifest_conflict_count: inputs
                .calibration_dataset_manifest_conflict_count,
            calibration_runs: inputs.calibration_runs,
        });
        let mut risk_code_counts = BTreeMap::new();
        for model in &risk.models {
            for code in &model.risk_codes {
                *risk_code_counts.entry(code.clone()).or_insert(0) += 1;
            }
        }
        if inputs.calibration_dataset_manifest_conflict_count > 0 {
            risk_code_counts.insert(
                RANKING_CALIBRATION_DATASET_MANIFEST_CONFLICT_REASON.to_string(),
                inputs.calibration_dataset_manifest_conflict_count,
            );
        }
        let stale_running_cutoff =
            inputs.generated_at - Duration::hours(TRACE_RANKING_WORKER_RUN_STALE_AFTER_HOURS);
        let mut running_worker_run_count = 0;
        let mut stale_running_worker_run_count = 0;
        let mut failed_worker_run_count = 0;
        for worker_run in inputs.worker_runs {
            match worker_run.status {
                TraceRankingWorkerRunStatus::Running => {
                    running_worker_run_count += 1;
                    if worker_run.created_at <= stale_running_cutoff {
                        stale_running_worker_run_count += 1;
                    }
                }
                TraceRankingWorkerRunStatus::Failed => {
                    failed_worker_run_count += 1;
                }
                TraceRankingWorkerRunStatus::Completed => {}
            }
        }
        Self {
            active_model_count: risk.active_model_count,
            monitored_model_count: risk.monitored_model_count,
            at_risk_model_count: risk.at_risk_model_count,
            risk_code_counts,
            backtest_model_target_count: backtest.evaluated_model_target_count,
            passing_backtest_model_target_count: backtest.passing_model_target_count,
            failing_backtest_model_target_count: backtest.failing_model_target_count,
            backtest_reason_counts: backtest.reason_code_counts,
            adjudication_issue_group_count: adjudication.issue_group_count,
            unresolved_disputed_label_group_count: adjudication
                .unresolved_disputed_label_group_count,
            conflicting_absolute_label_group_count: adjudication
                .conflicting_absolute_label_group_count,
            conflicting_preference_pair_count: adjudication.conflicting_preference_pair_count,
            adjudication_reason_counts: adjudication.reason_code_counts,
            pending_credit_event_count: readiness.pending_ranking_credit_event_count,
            ready_credit_event_count: readiness.ready_count,
            blocked_credit_event_count: readiness.blocked_count,
            blocked_credit_reason_counts: readiness.blocked_reason_counts,
            calibration_dataset_manifest_conflict_count: inputs
                .calibration_dataset_manifest_conflict_count,
            running_worker_run_count,
            stale_running_worker_run_count,
            failed_worker_run_count,
        }
    }
}

#[derive(Debug, Default, Serialize)]
struct TraceOperationalDelayedCreditSummary {
    event_count: usize,
    by_event_type: BTreeMap<String, usize>,
    points_positive: f32,
    points_negative: f32,
    points_total: f32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_event_at: Option<DateTime<Utc>>,
}

impl TraceOperationalDelayedCreditSummary {
    fn from_events(events: &[TraceCommonsCreditLedgerRecord]) -> Self {
        let mut summary = Self {
            event_count: events.len(),
            ..Self::default()
        };
        for event in events {
            *summary
                .by_event_type
                .entry(trace_operational_credit_event_type_name(event.event_type).to_string())
                .or_insert(0) += 1;
            if event.credit_points_delta >= 0.0 {
                summary.points_positive += event.credit_points_delta;
            } else {
                summary.points_negative += event.credit_points_delta;
            }
            summary.points_total += event.credit_points_delta;
            summary.last_event_at = Some(
                summary
                    .last_event_at
                    .map(|last_event_at| last_event_at.max(event.created_at))
                    .unwrap_or(event.created_at),
            );
        }
        summary
    }
}

fn is_zero(value: &usize) -> bool {
    *value == 0
}

fn suppress_small_analytics_cells(
    cells: &mut BTreeMap<String, usize>,
    min_cell_count: usize,
) -> usize {
    let before = cells.len();
    cells.retain(|_, count| *count >= min_cell_count);
    before.saturating_sub(cells.len())
}

impl IntoResponse for ApiError {
    fn into_response(self) -> axum::response::Response {
        Json(self).into_response()
    }
}

