    fn corrupt_submission_record_tenant(
        root: &Path,
        stored_tenant_id: &str,
        forged_tenant_id: &str,
        submission_id: Uuid,
    ) {
        let path = submission_metadata_path(root, stored_tenant_id, submission_id);
        let body = std::fs::read_to_string(&path).expect("metadata reads for corruption");
        let mut value: serde_json::Value =
            serde_json::from_str(&body).expect("metadata json parses");
        value["tenant_id"] = serde_json::json!(forged_tenant_id);
        value["tenant_storage_ref"] = serde_json::json!(tenant_storage_ref(forged_tenant_id));
        value["submitted_tenant_scope_ref"] =
            serde_json::json!(tenant_storage_ref(forged_tenant_id));
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&value).expect("metadata serializes"),
        )
        .expect("metadata corruption writes");
    }

    fn read_raw_audit_events(
        root: &Path,
        tenant_id: &str,
    ) -> anyhow::Result<Vec<TraceCommonsAuditEvent>> {
        let path = audit_log_path(root, tenant_id);
        let body = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read raw audit events {}", path.display()))?;
        body.lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(|line| serde_json::from_str(line).context("failed to parse raw audit event"))
            .collect()
    }

    #[test]
    fn token_role_parses_worker_roles() {
        let cases = [
            ("contributor", TokenRole::Contributor, "contributor"),
            ("reviewer", TokenRole::Reviewer, "reviewer"),
            ("admin", TokenRole::Admin, "admin"),
            ("export_worker", TokenRole::ExportWorker, "export_worker"),
            ("export-worker", TokenRole::ExportWorker, "export_worker"),
            (
                "retention_worker",
                TokenRole::RetentionWorker,
                "retention_worker",
            ),
            (
                "retention-worker",
                TokenRole::RetentionWorker,
                "retention_worker",
            ),
            ("vector_worker", TokenRole::VectorWorker, "vector_worker"),
            (
                "benchmark_worker",
                TokenRole::BenchmarkWorker,
                "benchmark_worker",
            ),
            ("utility_worker", TokenRole::UtilityWorker, "utility_worker"),
            ("utility-worker", TokenRole::UtilityWorker, "utility_worker"),
            (
                "process_eval_worker",
                TokenRole::ProcessEvalWorker,
                "process_eval_worker",
            ),
            (
                "process-evaluation-worker",
                TokenRole::ProcessEvalWorker,
                "process_eval_worker",
            ),
            (
                "revocation_worker",
                TokenRole::RevocationWorker,
                "revocation_worker",
            ),
            (
                "revocation-worker",
                TokenRole::RevocationWorker,
                "revocation_worker",
            ),
        ];

        for (raw, expected, storage_name) in cases {
            let parsed = TokenRole::parse(raw).expect("role parses");
            assert_eq!(parsed, expected);
            assert_eq!(parsed.storage_name(), storage_name);
        }
        assert!(TokenRole::parse("trainer").is_err());
    }

    #[test]
    fn trace_summary_similarity_exact_hash_wins_and_fuzzy_neighbors_are_ranked() {
        let target_submission =
            Uuid::parse_str("00000000-0000-0000-0000-000000000001").expect("uuid parses");
        let exact_trace =
            Uuid::parse_str("00000000-0000-0000-0000-000000000011").expect("uuid parses");
        let fuzzy_trace =
            Uuid::parse_str("00000000-0000-0000-0000-000000000012").expect("uuid parses");
        let unrelated_trace =
            Uuid::parse_str("00000000-0000-0000-0000-000000000013").expect("uuid parses");

        let neighbors = nearest_trace_neighbors(
            target_submission,
            "Task type: calendar scheduling timezone retry",
            "sha256:target",
            [
                TraceSimilarityCandidate {
                    submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000021")
                        .expect("uuid parses"),
                    trace_id: fuzzy_trace,
                    canonical_summary: Some(
                        "Task type: calendar scheduling timezone ambiguity retry",
                    ),
                    canonical_summary_hash: Some("sha256:fuzzy"),
                },
                TraceSimilarityCandidate {
                    submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000022")
                        .expect("uuid parses"),
                    trace_id: exact_trace,
                    canonical_summary: Some("different text but same hash"),
                    canonical_summary_hash: Some("sha256:target"),
                },
                TraceSimilarityCandidate {
                    submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000023")
                        .expect("uuid parses"),
                    trace_id: unrelated_trace,
                    canonical_summary: Some("database migration checksum repair"),
                    canonical_summary_hash: Some("sha256:unrelated"),
                },
            ],
        );

        assert_eq!(neighbors.len(), 2);
        assert_eq!(neighbors[0].trace_id, exact_trace.to_string());
        assert_eq!(neighbors[0].score, 1.0);
        assert_eq!(neighbors[1].trace_id, fuzzy_trace.to_string());
        assert!(neighbors[1].score > TRACE_SIMILARITY_NEIGHBOR_THRESHOLD);
        assert!(neighbors[1].score < 1.0);
    }

    #[test]
    fn trace_summary_similarity_excludes_same_submission_and_sorts_ties() {
        let target_submission =
            Uuid::parse_str("00000000-0000-0000-0000-000000000001").expect("uuid parses");
        let first_trace =
            Uuid::parse_str("00000000-0000-0000-0000-000000000011").expect("uuid parses");
        let second_trace =
            Uuid::parse_str("00000000-0000-0000-0000-000000000012").expect("uuid parses");

        let neighbors = nearest_trace_neighbors(
            target_submission,
            "tool call retry calendar auth failure",
            "sha256:target",
            [
                TraceSimilarityCandidate {
                    submission_id: target_submission,
                    trace_id: Uuid::parse_str("00000000-0000-0000-0000-000000000010")
                        .expect("uuid parses"),
                    canonical_summary: Some("tool call retry calendar auth failure"),
                    canonical_summary_hash: Some("sha256:target"),
                },
                TraceSimilarityCandidate {
                    submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000021")
                        .expect("uuid parses"),
                    trace_id: second_trace,
                    canonical_summary: Some("tool call retry calendar auth"),
                    canonical_summary_hash: Some("sha256:two"),
                },
                TraceSimilarityCandidate {
                    submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000022")
                        .expect("uuid parses"),
                    trace_id: first_trace,
                    canonical_summary: Some("tool call retry calendar auth"),
                    canonical_summary_hash: Some("sha256:one"),
                },
            ],
        );

        assert_eq!(
            neighbors
                .iter()
                .map(|neighbor| neighbor.trace_id.as_str())
                .collect::<Vec<_>>(),
            vec![first_trace.to_string(), second_trace.to_string()]
        );
    }

    async fn sample_envelope() -> TraceContributionEnvelope {
        let trace = TraceFile {
            model_name: "test-model".to_string(),
            memory_snapshot: Vec::new(),
            http_exchanges: Vec::new(),
            steps: vec![TraceStep {
                request_hint: None,
                response: TraceResponse::UserInput {
                    content: "Please inspect the workspace".to_string(),
                },
                expected_tool_results: Vec::new(),
            }],
        };
        let raw = trace_commons_protocol::trace_contribution::RawTraceContribution::from_recorded_trace(
            &trace,
            RecordedTraceContributionOptions {
                include_message_text: true,
                pseudonymous_contributor_id: Some("sha256:contributor".to_string()),
                tenant_scope_ref: Some("tenant_sha256:client".to_string()),
                ..Default::default()
            },
        );
        DeterministicTraceRedactor::default()
            .redact_trace(raw)
            .await
            .expect("redaction should succeed")
    }

    fn make_metadata_only_low_risk(envelope: &mut TraceContributionEnvelope) {
        envelope.privacy.residual_pii_risk = ResidualPiiRisk::Low;
        envelope.consent.message_text_included = false;
        envelope.consent.tool_payloads_included = false;
        for event in &mut envelope.events {
            event.redacted_content = None;
            event.structured_payload = serde_json::Value::Null;
        }
    }

    #[tokio::test]
    async fn submit_rescrubs_and_stores_under_authenticated_tenant() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let mut envelope = sample_envelope().await;
        envelope.events[0].redacted_content =
            Some("late leak at /tmp/ironclaw/private/token.txt".to_string());

        let Json(receipt) = submit_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(envelope.clone()),
        )
        .await
        .expect("submission succeeds");

        assert_eq!(receipt.status, "quarantined");
        let record = read_submission_record(temp.path(), "tenant-a", envelope.submission_id)
            .expect("record reads")
            .expect("record exists");
        assert_eq!(record.tenant_id, "tenant-a");
        assert_eq!(record.status, TraceCorpusStatus::Quarantined);
        let stored = std::fs::read_to_string(temp.path().join(record.object_key))
            .expect("stored envelope reads");
        assert!(stored.contains("server-rescrub-v1"));
        assert!(!stored.contains("/tmp/ironclaw/private/token.txt"));
    }

    #[tokio::test]
    async fn submit_ignores_forged_envelope_tenant_scope_at_store_boundary() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let mut envelope = sample_envelope().await;
        let submission_id = envelope.submission_id;
        envelope.contributor.tenant_scope_ref = Some(tenant_storage_ref("tenant-b"));

        let _ = submit_trace_handler(State(state), auth_headers("token-a"), Json(envelope))
            .await
            .expect("submission succeeds under authenticated tenant");

        let record = read_submission_record(temp.path(), "tenant-a", submission_id)
            .expect("tenant-a record reads")
            .expect("tenant-a record exists");
        assert_eq!(record.tenant_id, "tenant-a");
        assert_eq!(
            record.submitted_tenant_scope_ref.as_deref(),
            Some(tenant_storage_ref("tenant-a").as_str())
        );
        assert!(
            read_submission_record(temp.path(), "tenant-b", submission_id)
                .expect("tenant-b record lookup succeeds")
                .is_none()
        );
        assert!(!audit_log_path(temp.path(), "tenant-b").exists());
    }

