    #[test]
    fn parses_pairwise_ranking_policy_thresholds() {
        assert_eq!(
            parse_ranking_min_pairwise_label_count("0").expect("zero disables pairwise floor"),
            0
        );
        assert_eq!(
            parse_ranking_min_pairwise_label_count("25").expect("pairwise floor parses"),
            25
        );
        assert_eq!(
            parse_ranking_min_pairwise_accuracy_micros("0")
                .expect("zero disables pairwise accuracy floor"),
            0
        );
        assert_eq!(
            parse_ranking_min_pairwise_accuracy_micros("850000")
                .expect("pairwise accuracy floor parses"),
            850_000
        );

        let label_error = parse_ranking_min_pairwise_label_count("many")
            .expect_err("non-numeric pairwise floor is invalid");
        assert!(
            label_error
                .to_string()
                .contains(TRACE_COMMONS_RANKING_MIN_PAIRWISE_LABEL_COUNT)
        );
        let accuracy_error = parse_ranking_min_pairwise_accuracy_micros("1000001")
            .expect_err("over-range pairwise accuracy floor is invalid");
        assert!(
            accuracy_error
                .to_string()
                .contains(TRACE_COMMONS_RANKING_MIN_PAIRWISE_ACCURACY_MICROS)
        );
    }

    #[test]
    fn trace_object_store_kind_parses_operator_modes() {
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(None, false).expect("mode parses"),
            None
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(None, true).expect("mode parses"),
            Some(TraceEncryptedObjectStoreKind::LegacyArtifactSidecar)
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(Some("file"), true).expect("mode parses"),
            None
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(Some("local_encrypted"), false)
                .expect("mode parses"),
            Some(TraceEncryptedObjectStoreKind::LegacyArtifactSidecar)
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(Some("local_service"), false)
                .expect("mode parses"),
            Some(TraceEncryptedObjectStoreKind::ServiceLocal)
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(Some("remote_service"), false)
                .expect("mode parses"),
            Some(TraceEncryptedObjectStoreKind::ServiceRemote)
        );
        assert_eq!(
            TraceEncryptedObjectStoreKind::from_config(Some("service_owned_remote"), false)
                .expect("mode parses"),
            Some(TraceEncryptedObjectStoreKind::ServiceRemote)
        );

        let error = TraceEncryptedObjectStoreKind::from_config(Some("mystery_store"), false)
            .expect_err("unknown object store mode must fail");
        assert!(
            error
                .to_string()
                .contains("unsupported TRACE_COMMONS_OBJECT_STORE")
        );
    }

    #[test]
    fn remote_trace_object_store_config_requires_complete_production_intent() {
        let missing = TraceRemoteObjectStoreConfig::from_parts(None, None, None, None)
            .expect_err("remote mode without production env fails closed");
        assert!(
            missing
                .to_string()
                .contains(TRACE_COMMONS_REMOTE_OBJECT_STORE_PROVIDER)
        );

        let unsupported = TraceRemoteObjectStoreConfig::from_parts(
            Some("filesystem"),
            Some("trace-commons-prod-bucket"),
            Some("projects/prod/locations/global/keyRings/traces/cryptoKeys/envelope"),
            Some("secret-manager://trace-commons/remote-writer"),
        )
        .expect_err("unsupported remote provider fails closed");
        assert!(
            unsupported
                .to_string()
                .contains("unsupported TRACE_COMMONS_REMOTE_OBJECT_STORE_PROVIDER")
        );

        let config = TraceRemoteObjectStoreConfig::from_parts(
            Some("aws_s3"),
            Some("trace-commons-prod-bucket"),
            Some("arn:aws:kms:us-west-2:123456789012:key/trace-commons"),
            Some("aws-iam-role:trace-commons-writer"),
        )
        .expect("complete remote operator intent parses");
        assert_eq!(config.provider, TraceRemoteObjectStoreProvider::AwsS3);
        assert_eq!(
            config.status_object_store_alias(),
            TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
        );
    }

