    #[test]
    fn db_read_cutover_guard_requires_fail_closed_writes_when_reconciliation_is_required() {
        let gates = TraceTenantRolloutGates::for_feature(
            TraceTenantRolloutFeature::DbReviewerReads,
            &["tenant-a"],
        );

        let missing_global = validate_db_read_cutover_guard_config(
            &TraceTenantRolloutGates::default(),
            DbReadCutoverGuardConfig {
                require_db_reconciliation_clean: true,
                db_contributor_reads: true,
                ..DbReadCutoverGuardConfig::default()
            },
        )
        .expect_err("global DB reader promotion needs fail-closed mirror writes");
        assert!(
            missing_global
                .to_string()
                .contains("TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES")
        );

        let missing_allowlist = validate_db_read_cutover_guard_config(
            &gates,
            DbReadCutoverGuardConfig {
                require_db_reconciliation_clean: true,
                db_reviewer_reads: true,
                ..DbReadCutoverGuardConfig::default()
            },
        )
        .expect_err("tenant-allowlisted DB reader promotion needs fail-closed mirror writes");
        assert!(
            missing_allowlist
                .to_string()
                .contains("TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES")
        );

        validate_db_read_cutover_guard_config(
            &gates,
            DbReadCutoverGuardConfig {
                require_db_reconciliation_clean: true,
                require_db_mirror_writes: true,
                db_reviewer_reads: true,
                ..DbReadCutoverGuardConfig::default()
            },
        )
        .expect("fail-closed mirror writes allow DB reader promotion");

        validate_db_read_cutover_guard_config(
            &gates,
            DbReadCutoverGuardConfig {
                db_reviewer_reads: true,
                ..DbReadCutoverGuardConfig::default()
            },
        )
        .expect("non-production reconciliation mode does not force fail-closed writes");
    }

    #[test]
    fn object_primary_submit_review_validates_production_guards() {
        validate_object_primary_submit_review_config(
            true,
            true,
            true,
            true,
            true,
            Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
        )
        .expect("complete production guard config is valid");

        let cases = [
            (
                false,
                true,
                true,
                true,
                Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
                "TRACE_COMMONS_DB_DUAL_WRITE",
            ),
            (
                true,
                false,
                true,
                true,
                Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
                "TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES",
            ),
            (
                true,
                true,
                false,
                true,
                Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
                "TRACE_COMMONS_DB_REVIEWER_READS",
            ),
            (
                true,
                true,
                true,
                false,
                Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
                "TRACE_COMMONS_DB_REVIEWER_REQUIRE_OBJECT_REFS",
            ),
            (true, true, true, true, None, "TRACE_COMMONS_OBJECT_STORE"),
            (
                true,
                true,
                true,
                true,
                Some(TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE),
                "TRACE_COMMONS_OBJECT_STORE",
            ),
        ];
        for (
            db_mirror_configured,
            require_db_mirror_writes,
            db_reviewer_reads,
            db_reviewer_require_object_refs,
            artifact_store_name,
            expected,
        ) in cases
        {
            let error = validate_object_primary_submit_review_config(
                true,
                db_mirror_configured,
                require_db_mirror_writes,
                db_reviewer_reads,
                db_reviewer_require_object_refs,
                artifact_store_name,
            )
            .expect_err("incomplete object-primary config must fail");
            assert!(
                error.to_string().contains(expected),
                "expected {expected} in {error}"
            );
        }
    }

