    #[test]
    fn audit_chain_verifier_reports_mismatched_file_event_tenant() {
        let temp = tempfile::tempdir().expect("temp dir");
        let path = audit_log_path(temp.path(), "tenant-a");
        std::fs::create_dir_all(path.parent().expect("audit parent")).expect("create audit dir");
        let mut forged = TraceCommonsAuditEvent {
            event_id: Uuid::new_v4(),
            tenant_id: "tenant-b".to_string(),
            submission_id: Uuid::nil(),
            kind: "read".to_string(),
            created_at: Utc::now(),
            status: None,
            actor_role: Some(TokenRole::Reviewer),
            actor_principal_ref: Some(principal_storage_ref("review-token-a")),
            reason: Some("mismatched audit tenant".to_string()),
            export_count: Some(1),
            export_id: None,
            decision_inputs_hash: None,
            previous_event_hash: Some(TRACE_AUDIT_EVENT_GENESIS_HASH.to_string()),
            event_hash: None,
        };
        forged.event_hash = Some(
            compute_audit_event_hash(TRACE_AUDIT_EVENT_GENESIS_HASH, &forged)
                .expect("forged audit hash computes"),
        );
        std::fs::write(
            &path,
            format!(
                "{}\n",
                serde_json::to_string(&forged).expect("forged audit event serializes")
            ),
        )
        .expect("forged audit event writes");

        let report =
            verify_file_audit_chain(temp.path(), "tenant-a").expect("audit chain verifier runs");

        assert!(!report.verified);
        assert_eq!(report.event_count, 1);
        assert_eq!(report.mismatch_count, 1);
        assert!(
            report
                .failures
                .iter()
                .any(|failure| failure.contains("tenant mismatch")),
            "{:?}",
            report.failures
        );
    }

    #[tokio::test]
    async fn maintenance_can_verify_file_audit_chain() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let envelope = sample_envelope().await;
        let _ = submit_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(envelope),
        )
        .await
        .expect("submission succeeds");

        let Json(response) = maintenance_handler(
            State(state.clone()),
            auth_headers("admin-token-a"),
            Json(TraceMaintenanceRequest {
                purpose: Some("audit_chain_verify".to_string()),
                dry_run: true,
                backfill_db_mirror: false,
                index_vectors: false,
                reconcile_db_mirror: false,
                verify_audit_chain: true,
                prune_export_cache: false,
                max_export_age_hours: None,
                purge_expired_before: None,
            }),
        )
        .await
        .expect("maintenance verifies audit chain");
        let report = response.audit_chain.expect("audit chain report exists");
        assert!(report.verified);
        assert_eq!(report.event_count, 2);
        assert_eq!(report.mismatch_count, 0);

        let path = audit_log_path(temp.path(), "tenant-a");
        let body = std::fs::read_to_string(&path).expect("audit log reads");
        std::fs::write(
            &path,
            body.replacen("\"submitted\"", "\"submitted_tampered\"", 1),
        )
        .expect("tamper audit log");

        let Json(response) = maintenance_handler(
            State(state),
            auth_headers("admin-token-a"),
            Json(TraceMaintenanceRequest {
                purpose: Some("audit_chain_verify_after_tamper".to_string()),
                dry_run: true,
                backfill_db_mirror: false,
                index_vectors: false,
                reconcile_db_mirror: false,
                verify_audit_chain: true,
                prune_export_cache: false,
                max_export_age_hours: None,
                purge_expired_before: None,
            }),
        )
        .await
        .expect("maintenance reports audit chain tampering");
        let report = response.audit_chain.expect("audit chain report exists");
        assert!(!report.verified);
        assert!(report.mismatch_count >= 1);
        assert!(
            report
                .failures
                .iter()
                .any(|failure| failure.contains("event_hash mismatch"))
        );
    }

