    #[tokio::test]
    async fn contributor_sees_own_delayed_credit_events_in_summary() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let mut envelope = sample_envelope().await;
        make_metadata_only_low_risk(&mut envelope);
        envelope.consent.scopes = vec![ConsentScope::ModelTraining];
        envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
        envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
        let submission_id = envelope.submission_id;

        let _ = submit_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(envelope),
        )
        .await
        .expect("submission succeeds");

        let Json(event) = append_credit_event_handler(
            State(state.clone()),
            auth_headers("review-token-a"),
            AxumPath(submission_id),
            Json(TraceCreditLedgerAppendRequest {
                event_type: TraceCreditLedgerEventType::TrainingUtility,
                credit_points_delta: 1.75,
                reason: Some("training utility job selected this trace".to_string()),
                external_ref: Some("training-job:summary-ranker-smoke".to_string()),
            }),
        )
        .await
        .expect("reviewer can append delayed credit");

        let Json(events) = credit_events_handler(State(state.clone()), auth_headers("token-a"))
            .await
            .expect("contributor can list own credit events");
        assert_eq!(events.len(), 1);
        assert_eq!(events[0].event_id, event.event_id);

        let Json(credit) = credit_handler(State(state.clone()), auth_headers("token-a"))
            .await
            .expect("credit summary succeeds");
        assert_eq!(credit.credit_points_ledger, 1.75);
        assert_eq!(credit.credit_points_final, 0.0);
        assert_eq!(credit.credit_points_total, 1.75);

        let Json(statuses) = submission_status_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(TraceSubmissionStatusRequest {
                submission_ids: vec![submission_id],
            }),
        )
        .await
        .expect("contributor can sync delayed credit status");
        assert_eq!(statuses.len(), 1);
        assert_eq!(statuses[0].credit_points_ledger, 1.75);
        assert_eq!(statuses[0].credit_points_final, None);
        assert_eq!(statuses[0].credit_points_total, Some(1.75));
        assert!(
            statuses[0]
                .delayed_credit_explanations
                .iter()
                .any(|explanation| explanation.contains("TrainingUtility"))
        );

        let revoke_status = revoke_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            AxumPath(submission_id),
        )
        .await
        .expect("contributor can revoke trace with existing delayed credit");
        assert_eq!(revoke_status, StatusCode::NO_CONTENT);

        let Json(events_after_revoke) =
            credit_events_handler(State(state.clone()), auth_headers("token-a"))
                .await
                .expect(
                    "credit events remain hidden from contributor projections after revocation",
                );
        assert!(
            events_after_revoke.is_empty(),
            "terminal trace credit events remain in the audit ledger but are hidden from contributor credit projections"
        );

        let Json(credit_after_revoke) =
            credit_handler(State(state.clone()), auth_headers("token-a"))
                .await
                .expect("credit summary succeeds after revocation");
        assert_eq!(credit_after_revoke.revoked, 1);
        assert_eq!(credit_after_revoke.credit_points_ledger, 0.0);
        assert_eq!(credit_after_revoke.credit_points_final, 0.0);
        assert_eq!(credit_after_revoke.credit_points_total, 0.0);

        let Json(statuses_after_revoke) = submission_status_handler(
            State(state),
            auth_headers("token-a"),
            Json(TraceSubmissionStatusRequest {
                submission_ids: vec![submission_id],
            }),
        )
        .await
        .expect("contributor can sync revoked delayed credit status");
        assert_eq!(statuses_after_revoke.len(), 1);
        assert_eq!(statuses_after_revoke[0].status, "revoked");
        assert_eq!(statuses_after_revoke[0].credit_points_ledger, 0.0);
        assert_eq!(statuses_after_revoke[0].credit_points_final, Some(0.0));
        assert_eq!(statuses_after_revoke[0].credit_points_total, None);
        assert!(
            statuses_after_revoke[0]
                .explanation
                .iter()
                .any(|explanation| explanation.contains("Revoked"))
        );
        assert!(
            statuses_after_revoke[0]
                .delayed_credit_explanations
                .iter()
                .any(|explanation| {
                    explanation.contains("retained for audit")
                        && explanation.contains("excluded because the trace is revoked")
                })
        );
    }

    #[tokio::test]
    async fn admin_credit_settlement_finalizes_pending_utility_once_and_enqueues_near_receipt() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let mut envelope = sample_envelope().await;
        make_metadata_only_low_risk(&mut envelope);
        envelope.consent.scopes = vec![ConsentScope::ModelTraining];
        envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
        envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
        let submission_id = envelope.submission_id;

        let _ = submit_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(envelope),
        )
        .await
        .expect("submission succeeds");

        let Json(event) = append_credit_event_handler(
            State(state.clone()),
            auth_headers("review-token-a"),
            AxumPath(submission_id),
            Json(TraceCreditLedgerAppendRequest {
                event_type: TraceCreditLedgerEventType::TrainingUtility,
                credit_points_delta: 1.75,
                reason: Some("frontier lab training utility attested".to_string()),
                external_ref: Some("lab-attestation:batch-42".to_string()),
            }),
        )
        .await
        .expect("reviewer can append delayed utility credit");

        let Json(dry_run) = credit_settlement_handler(
            State(state.clone()),
            auth_headers("admin-token-a"),
            Json(TraceCreditSettlementRunRequest {
                dry_run: true,
                policy_version: "trace-credit-policy-v1".to_string(),
                reason: "preview canary settlement".to_string(),
                near_contract_id: Some("trace-credits.testnet".to_string()),
                ranking_model_version: None,
                ranking_target_use: None,
            }),
        )
        .await
        .expect("admin can dry-run settlement");
        assert!(dry_run.dry_run);
        assert_eq!(dry_run.settled_source_event_count, 1);
        assert_eq!(dry_run.settled_credit_points, 1.75);
        assert!(
            read_all_credit_settlement_batches(temp.path(), "tenant-a")
                .expect("settlement reads")
                .is_empty()
        );
        assert!(
            read_all_near_credit_outbox_items(temp.path(), "tenant-a")
                .expect("outbox reads")
                .is_empty()
        );

        let Json(finalized) = credit_settlement_handler(
            State(state.clone()),
            auth_headers("admin-token-a"),
            Json(TraceCreditSettlementRunRequest {
                dry_run: false,
                policy_version: "trace-credit-policy-v1".to_string(),
                reason: "finalize canary settlement".to_string(),
                near_contract_id: Some("trace-credits.testnet".to_string()),
                ranking_model_version: None,
                ranking_target_use: None,
            }),
        )
        .await
        .expect("admin can finalize settlement");
        assert!(!finalized.dry_run);
        assert_eq!(finalized.settled_source_event_count, 1);
        assert_eq!(finalized.settled_credit_points, 1.75);
        assert_eq!(finalized.near_outbox_item_count, 1);

        let Json(retry) = credit_settlement_handler(
            State(state.clone()),
            auth_headers("admin-token-a"),
            Json(TraceCreditSettlementRunRequest {
                dry_run: false,
                policy_version: "trace-credit-policy-v1".to_string(),
                reason: "retry canary settlement".to_string(),
                near_contract_id: Some("trace-credits.testnet".to_string()),
                ranking_model_version: None,
                ranking_target_use: None,
            }),
        )
        .await
        .expect("settlement retry is idempotent");
        assert_eq!(retry.settled_source_event_count, 0);
        assert_eq!(retry.near_outbox_item_count, 0);

        let Json(credit) = credit_handler(State(state.clone()), auth_headers("token-a"))
            .await
            .expect("credit summary succeeds");
        assert_eq!(credit.credit_points_pending_ledger, 0.0);
        assert_eq!(credit.credit_points_settled, 1.75);
        assert_eq!(credit.credit_points_total, 1.75);
        assert_eq!(
            credit.last_settlement_batch_id,
            Some(finalized.settlement_batch_id)
        );

        let batches =
            read_all_credit_settlement_batches(temp.path(), "tenant-a").expect("settlement reads");
        assert_eq!(batches.len(), 1);
        assert_eq!(batches[0].source_credit_event_ids, vec![event.event_id]);

        let outbox =
            read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
        assert_eq!(outbox.len(), 1);
        assert_eq!(outbox[0].near_call.method_name, "settle_credit_receipt");
        let outbox_json = serde_json::to_string(&outbox[0]).expect("outbox serializes");
        assert!(!outbox_json.contains("frontier lab training utility attested"));
        assert!(!outbox_json.contains("token-a"));

        let Json(submitted) = mark_near_credit_outbox_status_handler(
            State(state),
            auth_headers("utility-worker-token-a"),
            Json(TraceNearCreditOutboxStatusRequest {
                near_outbox_id: outbox[0].near_outbox_id,
                status: StorageTraceCreditSettlementNearStatus::Submitted,
                near_transaction_hash: Some("near-public-tx-hash-1".to_string()),
                error_detail: None,
            }),
        )
        .await
        .expect("utility worker can mark NEAR receipt submitted");
        assert_eq!(
            submitted.status,
            StorageTraceCreditSettlementNearStatus::Submitted
        );
        assert_eq!(
            submitted.near_transaction_hash.as_deref(),
            Some("near-public-tx-hash-1")
        );
        assert!(submitted.submitted_at.is_some());
    }

