    async fn seed_pairwise_ranking_prediction_source(
        state: Arc<AppState>,
        candidate: &TraceRankingModelVersionRecord,
        fixture_key: &str,
        predicted_utility_micros: i64,
    ) -> TraceRankingPredictionRecord {
        let mut envelope = sample_envelope().await;
        make_metadata_only_low_risk(&mut envelope);
        envelope.consent.scopes = vec![ConsentScope::RankingTraining];
        envelope.trace_card.consent_scope = ConsentScope::RankingTraining;
        envelope.trace_card.allowed_uses = vec![TraceAllowedUse::RankingModelTraining];
        let submission_id = envelope.submission_id;
        let _ = submit_trace_handler(
            State(state.clone()),
            auth_headers("token-a"),
            Json(envelope),
        )
        .await
        .expect("pairwise source submission succeeds");
        let Json(feature) = ranking_feature_handler(
            State(state.clone()),
            auth_headers("utility-worker-token-a"),
            Json(TraceRankingFeatureRequest {
                submission_id,
                target_use: TraceAllowedUse::RankingModelTraining,
                feature_schema_version: candidate.feature_schema_version.clone(),
                feature_vector_hash: format!("sha256:{fixture_key}-feature-vector"),
                feature_names_hash: format!("sha256:{fixture_key}-feature-names"),
                source_feature_hash: format!("sha256:{fixture_key}-source-feature"),
                duplicate_score: Some(0.02),
                novelty_score: Some(0.9),
                privacy_risk_score: Some(0.01),
                quality_score: Some(0.91),
                coverage_tags: vec![fixture_key.to_string()],
            }),
        )
        .await
        .expect("utility worker can write pairwise feature");
        let Json(prediction) = ranking_prediction_handler(
            State(state.clone()),
            auth_headers("utility-worker-token-a"),
            Json(TraceRankingPredictionRequest {
                submission_id,
                target_use: TraceAllowedUse::RankingModelTraining,
                model_version: candidate.model_version.clone(),
                feature_schema_version: candidate.feature_schema_version.clone(),
                prediction_policy_version: candidate.policy_version.clone(),
                feature_vector_hash: feature.feature_vector_hash,
                predicted_utility_micros,
                uncertainty_micros: 100_000,
                confidence: 0.95,
                risk_penalty_micros: 0,
                novelty_bonus_micros: 0,
                explanation_codes: vec![fixture_key.replace('-', "_")],
            }),
        )
        .await
        .expect("utility worker can write pairwise prediction");
        prediction
    }

    #[tokio::test]
    async fn credit_cycle_worker_runs_ranking_credit_settlement_sequence() {
        let temp = tempfile::tempdir().expect("temp dir");
        let state = test_state(temp.path().to_path_buf());
        let (candidate, prediction) =
            seed_credit_cycle_ready_candidate(state.clone(), "trace-ranker-credit-cycle-v1").await;

        let Json(cycle) = credit_cycle_worker_run_handler(
            State(state.clone()),
            auth_headers("utility-worker-token-a"),
            Json(TraceCreditCycleWorkerRunRequest {
                dry_run: false,
                submit_near_outbox: false,
                confirm_near_outbox: false,
                target_use: TraceAllowedUse::RankingModelTraining,
                model_version: candidate.model_version.clone(),
                policy_version: candidate.policy_version.clone(),
                reason: "scheduled credit cycle".to_string(),
                near_contract_id: Some("trace-credits.testnet".to_string()),
                calibration_limit: Some(10),
                model_promotion_limit: Some(10),
                prediction_credit_limit: Some(10),
                credit_settlement_limit: Some(10),
                near_outbox_limit: Some(10),
                near_outbox_confirm_limit: Some(10),
                min_label_count: Some(1),
                confidence_threshold: Some(0.5),
                max_average_absolute_error_micros: Some(100_000),
                allow_at_risk_models: false,
            }),
        )
        .await
        .expect("utility worker can run the bounded credit cycle");

        assert!(!cycle.dry_run);
        assert_eq!(cycle.model_version, candidate.model_version);
        assert_eq!(cycle.calibration.calibrated_count, 1);
        assert_eq!(cycle.model_promotion.promoted_count, 1);
        assert_eq!(cycle.prediction_credit.credited_count, 1);
        assert_eq!(cycle.settlement.settled_source_event_count, 1);
        assert_eq!(cycle.settlement.near_outbox_item_count, 1);
        assert!(cycle.near_outbox_submit.dry_run);
        assert_eq!(cycle.near_outbox_submit.checked, 1);
        assert_eq!(cycle.near_outbox_submit.pending, 1);
        assert!(cycle.near_outbox_confirm.dry_run);
        assert_eq!(cycle.near_outbox_confirm.checked, 0);

        let credit_events = read_all_credit_events(temp.path(), "tenant-a")
            .expect("credit events read after cycle");
        assert!(credit_events.iter().any(|event| {
            event.external_ref.as_deref()
                == Some(&format!(
                    "ranking_prediction:{}",
                    prediction.ranking_prediction_id
                ))
        }));
        let outbox =
            read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
        assert_eq!(outbox.len(), 1);
        assert_eq!(outbox[0].near_call.method_name, "settle_credit_receipt");
        assert_eq!(
            outbox[0].status,
            StorageTraceCreditSettlementNearStatus::Pending
        );
        let worker_runs =
            read_all_ranking_worker_runs(temp.path(), "tenant-a").expect("worker runs read");
        let credit_cycle_runs = worker_runs
            .iter()
            .filter(|run| run.run_kind == TraceRankingWorkerRunKind::CreditCycle)
            .collect::<Vec<_>>();
        assert_eq!(credit_cycle_runs.len(), 1);
        assert_eq!(
            credit_cycle_runs[0].status,
            TraceRankingWorkerRunStatus::Completed
        );
        assert_eq!(
            credit_cycle_runs[0].model_version.as_deref(),
            Some(candidate.model_version.as_str())
        );
        assert_eq!(
            credit_cycle_runs[0].policy_version.as_deref(),
            Some(candidate.policy_version.as_str())
        );
        assert_eq!(
            credit_cycle_runs[0].target_use,
            Some(TraceAllowedUse::RankingModelTraining)
        );
        assert_eq!(
            credit_cycle_runs[0].checked_count,
            TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT
        );
        assert_eq!(
            credit_cycle_runs[0].succeeded_count,
            TRACE_CREDIT_CYCLE_WORKER_STEP_COUNT
        );
        assert!(
            credit_cycle_runs[0]
                .result_refs
                .iter()
                .any(|result_ref| result_ref.starts_with("credit_settlement_batch:"))
        );
    }

